        gpiod_unexport(fd);
        gpiod_line_close(fd);
        return -1;
    }

    // Add GPIO line to sysfs
    char sysfs_path[64];
    snprintf(sysfs_path, sizeof(sysfs_path), "/sys/class/gpio/gpio%d", GPIO_PIN_1);
    FILE *sysfs_file = fopen(sysfs_path, "w");
    if (!sysfs_file) {
        fprintf(stderr, "Error opening GPIO sysfs file for %s: %s\n", GPIO_DEVICE_1, gpiod_strerror(fd));
        gpiod_unexport(fd);
        gpiod_line_close(fd);
        return -1;
