    int ret;

    line = gpiod_line_get(gpio_number);
    if (!line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio_number);
        return -1;
    }

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO %d to %d: %d\n", gpio_number, state, ret);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to report the state of a GPIO pin
void report_gpio_state(int gpio_number) {
    int state = gpiod_line_get_value(gpiod_line_get(gpio_number));
    if (state < 0) {
        fprintf(stderr, "Error: Could not get GPIO %d value\n", gpio_number);
        return;
    }

    printf("GPIO %d: %d\n", gpio_number, state);
}

int main() {
