    signal(SIGINT, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio(GPIO_17) < 0 || initialize_gpio(GPIO_18) < 0) {
        fprintf(stderr, "Error: GPIO initialization failed\n");
        return 1;
    }

    printf("GPIO 17: %d, GPIO 18: %d\n", GPIO_17, GPIO_18);

    // Main loop
