        usleep(100000); // 100ms delay
    }

    // Cleanup GPIO lines
    printf("Cleaning up GPIO pins...\n");
    set_gpio_state(GPIO_17, 0); // Set GPIO 17 to 0
    set_gpio_state(GPIO_18, 0); // Set GPIO 18 to 0

    // Release GPIO lines
    printf("Releasing GPIO lines...\n");
    gpiod_line_release(gpiod_line_get(GPIO_17));
    gpiod_line_release(gpiod_line_get(GPIO_18));

