// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define timeout in microseconds
#define TIMEOUT_US 1000000

// Global variable to track program state
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio(int trigger_pin, int echo_pin) {
    int ret = gpiod_export(trigger_pin);
    if (ret < 0) {
        fprintf(stderr, "Error exporting GPIO %d: %d\n", trigger_pin, ret);
        return -1;
    }

    ret = gpiod_set_direction(trigger_pin, GPIOD_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting direction for GPIO %d: %d\n", trigger_pin, ret);
        gpiod_unexport(trigger_pin);
        return -1;
    }

    ret = gpiod_set_edge_type(trigger_pin, GPIOD_EDGE_RISING);
    if (ret < 0) {
        fprintf(stderr, "Error setting edge type for GPIO %d: %d\n", trigger_pin, ret);
        gpiod_unexport(trigger_pin);
        return -1;
    }

    ret = gpiod_set_active(trigger_pin);
    if (ret < 0) {
        fprintf(stderr, "Error setting active for GPIO %d: %d\n", trigger_pin, ret);
        gpiod_unexport(trigger_pin);
        return -1;
    }

    ret = gpiod_set_active(echo_pin);
    if (ret < 0) {
        fprintf(stderr, "Error setting active for GPIO %d: %d\n", echo_pin, ret);
        gpiod_unexport(trigger_pin);
        return -1;
    }

    return 0;
}

// Function to measure distance using HC-SR04
float measure_distance(int trigger_pin, int echo_pin) {
    struct timespec start, end;
    long long diff;

    // Trigger the sensor
    gpio_set_direction(trigger_pin, GPIOD_DIR_OUT);
    gpio_set_value(trigger_pin, 0);
    usleep(10); // 10us trigger pulse
    gpio_set_value(trigger_pin, 1);
    usleep(10); // 10us pulse
    gpio_set_value(trigger_pin, 0);

    // Measure the echo pulse
    struct timespec start_time, end_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (gpio_get_value(echo_pin) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        diff = (end_time.tv_sec - start_time.tv_sec) * 1000000000LL + (end_time.tv_nsec - start_time.tv_nsec);
        if (diff > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1.0; // Timeout
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (gpio_get_value(echo_pin) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        diff = (end_time.tv_sec - start_time.tv_sec) * 1000000000LL + (end_time.tv_nsec - start_time.tv_nsec);
        if (diff > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1.0; // Timeout
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &end_time);

    // Calculate the pulse width
    long long pulse_width = diff;

    // Calculate the distance in centimeters
    float distance = (pulse_width * 1.0) / 29.1;

    return distance;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(TRIGGER_PIN, ECHO_PIN) != 0) {
        return 1;
    }

    printf("HC-SR04 sensor initialized on GPIO %d and %d\n", TRIGGER_PIN, ECHO_PIN);

    // Main loop
    while (program_running) {
        float distance = measure_distance(TRIGGER_PIN, ECHO_PIN);

        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error measuring distance\n");
        }

        sleep(1);
    }

    // Cleanup GPIO
    gpio_set_value(TRIGGER_PIN, 0);
    gpio_set_value(ECHO_PIN, 0);
    gpio_unexport(TRIGGER_PIN);
    gpio_unexport(ECHO_PIN);

    return 0;
}

