// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read a single ADC value from the specified channel
int read_adc(int i2c_handle, int channel)
{
    char buf[2];
    int16_t adc_value;

    // Write the channel address to the I2C device
    if (i2cWriteByteData(i2c_handle, 0x00, channel) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Read two bytes from the I2C device
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    adc_value = (buf[0] << 8) | buf[1];

    return adc_value;
}

// Function to validate the ADC reading
int validate_reading(int adc_value)
{
    // Check if the ADC value is within the expected range (0-4095)
    if (adc_value < 0 || adc_value > 4095) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return 0;
}

int main()
{
    int i2c_handle;
    int adc_value;
    int valid_reading;
    int i;

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Main loop to read and validate ADC values
    while (!terminate) {
        // Open the I2C device
        i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
            gpioTerminate();
            return 1;
        }

        // Read the ADC value
        adc_value = read_adc(i2c_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Validate the ADC reading
        valid_reading = validate_reading(adc_value);
        if (valid_reading < 0) {
            fprintf(stderr, "Error validating ADC reading\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Print the ADC value to standard output
        printf("ADC Value: %d\n", adc_value);

        // Wait for 5 seconds
        sleep(5);
    }

