#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define the I2C address of the ADS1115
#define ADS1115_ADDR 0x48

// Define the I2C bus number (usually 1 on Raspberry Pi)
#define I2C_BUS 1

// Define the ADC channel to read (0-7)
#define ADC_CHANNEL 0

// Global variable to store the I2C handle
int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read a single ADC channel from the ADS1115
int read_ads1115(int i2c_handle, int channel) {
    char buf[2];
    int16_t adc_value;

    // Write the channel address to the I2C device
    if (i2cWriteByteData(i2c_handle, 0x00, channel) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Read the two bytes of ADC data from the I2C device
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes to form the ADC value
    adc_value = (buf[0] << 8) | buf[1];

    return adc_value;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop to read and print ADC values
    while (1) {
        int adc_value = read_ads1115(i2c_handle, ADC_CHANNEL);
        if (adc_value >= 0) {
            printf("ADC Value: %d\n", adc_value);
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

