// Function to measure distance using HC-SR04
float measure_distance(int trigger_pin, int echo_pin) {
    struct timespec start, end;
    long long diff;

    // Trigger the sensor
    gpio_set_direction(trigger_pin, GPIOD_OUT);
    gpio_set_value(trigger_pin, 0);
    usleep(10); // 10us trigger pulse
    gpio_set_value(trigger_pin, 1);
    usleep(10); // 10us pulse
    gpio_set_direction(trigger_pin, GPIOD_IN);

    // Measure the echo pulse
    struct timespec start_time, end_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (gpio_get_value(echo_pin) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        diff = (end_time.tv_sec - start_time.tv_sec) * 1000000000LL + (end_time.tv_nsec - start_time.tv_nsec);
        if (diff > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1.0; // Timeout
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (gpio_get_value(echo_pin) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        diff = (end_time.tv_sec - start_time.tv_sec) * 1000000000LL + (end_time.tv_nsec - start_time.tv_nsec);
        if (diff > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1.0; // Timeout
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &end_time);

    diff = (end_time.tv_sec - start_time.tv_sec) * 1000000000LL + (end_time.tv_nsec - start_time.tv_nsec);
    if (diff > TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo pulse\n");
        return -1.0; // Timeout
    }

    // Calculate distance in centimeters
    float distance = (float)diff / 29.1; // Speed of sound in air is approximately 29.1 cm/us
    return distance;
}

// Function to report the distance
void report_distance(float distance) {
    if (distance < 0) {
        fprintf(stderr, "Error: Distance measurement failed.\n");
    } else {
        printf("Distance: %.2f cm\n", distance);
    }
}

