int initialize_gpio(int gpio_pin, int gpio_group) {
    int fd;
    struct gpiod_line *line;

    // Open GPIO line
    fd = gpiod_line_open(gpio_group, gpio_pin, GPIOD_LINE_DIRECTION_OUTPUT);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO line %d on group %s: %s\n", gpio_pin, gpio_group, strerror(errno));
        return -1;
    }

    // Get the line
    line = gpiod_line_get(fd);
    if (!line) {
        fprintf(stderr, "Error getting line %d on group %s\n", gpio_pin, gpio_group);
        gpiod_line_release(fd);
        return -1;
    }

    // Set GPIO direction to output
    if (gpiod_line_set_direction(fd, GPIOD_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "Error setting direction for GPIO line %d on group %s\n", gpio_pin, gpio_group);
        gpiod_line_release(fd);
        return -1;
    }

    // Attach interrupt handler
    if (gpiod_line_request_interrupt(fd, GPIOD_LINE_INTERRUPT_EDGE_FALLING, 0, signal_handler) < 0) {
        fprintf(stderr, "Error requesting interrupt for GPIO line %d on group %s\n", gpio_pin, gpio_group);
        gpiod_line_release(fd);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio(int gpio_pin, int gpio_group) {
    int fd;
    struct gpiod_line *line;

    // Close GPIO line
    fd = gpiod_line_get(fd);
    if (fd >= 0) {
        gpiod_line_release(fd);
    }

    // Unrequest interrupt
    if (gpiod_line_unrequest_interrupt(fd) < 0) {
        fprintf(stderr, "Error unrequesting interrupt for GPIO line %d on group %s\n", gpio_pin, gpio_group);
    }
}

