#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE B115200
#define BUFFER_SIZE 1024

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int fd;
    struct termios tty;
    char buffer[BUFFER_SIZE];
    int bytes_read;
    int bytes_written;
    int i;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the serial port
    fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening serial port");
        return 1;
    }

    // Set the serial port parameters
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting serial port attributes");
        close(fd);
        return 1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD; // B115200 8N1
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode
    tty.c_cc[VMIN] = 0; // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting serial port attributes");
        close(fd);
        return 1;
    }

    printf("Serial port opened. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read from the serial port
        bytes_read = read(fd, buffer, BUFFER_SIZE - 1);
        if (bytes_read == -1) {
            if (errno == EAGAIN || errno == EINTR) {
                // No data available, continue
            } else {
                perror("Error reading from serial port");
                break;
            }
        } else {
            buffer[bytes_read] = '\0'; // Null-terminate the buffer
            printf("Received: %s\n", buffer);
        }

        // Write to the serial port
        bytes_written = write(fd, buffer, bytes_read);
        if (bytes_written == -1) {
            perror("Error writing to serial port");
            break;
        }
    }

    // Close the serial port
    close(fd);

    printf("Serial port closed.\n");

    return 0;
}

