    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpio_unexport(GPIO_PIN);
    exit(0);
}

// Exports the specified GPIO pin
int gpio_export(int pin) {
    struct gpiod_export_request *request = malloc(sizeof(struct gpiod_export_request));
    if (!request) {
        perror("Failed to allocate memory for gpio_export_request");
        return -1;
    }

    request->gpio = pin;
    request->flags = 0; // No flags for now

    int fd = gpiod_export(request);
    if (fd < 0) {
        perror("Failed to export GPIO");
        free(request);
        return -1;
    }

    printf("GPIO %d exported successfully\n", pin);
    return fd;
}

// Unexports the specified GPIO pin
int gpio_unexport(int pin) {
    int fd = gpiod_unexport(pin);
    if (fd < 0) {
        perror("Failed to unexport GPIO");
        return -1;
    }

    printf("GPIO %d unexported successfully\n", pin);
    return fd;
}

// Sets the direction of the specified GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    int fd = gpiod_get_direction(pin);
    if (fd < 0) {
        perror("Failed to get direction for GPIO");
        return -1;
    }

    int ret = gpiod_set_direction(pin, direction);
    if (ret < 0) {
        perror("Failed to set direction for GPIO");
        return -1;
    }

    printf("GPIO %d set direction to %s\n", pin, direction);
    return fd;
}

// Reads the value of the specified GPIO pin
int gpio_read(int pin) {
    int fd = gpiod_get_value(pin);
    if (fd < 0) {
        perror("Failed to get value for GPIO");
        return -1;
    }

    int value = gpiod_get_value(pin);
    if (value < 0) {
        perror("Failed to get value for GPIO");
        return -1;
    }

    return value;
}

// Writes the specified value to the specified GPIO pin
int gpio_write(int pin, int value) {
    int fd = gpiod_get_value(pin);
    if (fd < 0) {
        perror("Failed to get value for GPIO");
        return -1;
    }

    int ret = gpiod_set_value(pin, value);
    if (ret < 0) {
        perror("Failed to set value for GPIO");
        return -1;
    }

    return ret;
}

