    int current_state;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize libgpiod
    if (gpiod_line_request_output(GPIO_PIN, GPIO_MODE, 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d output\n", GPIO_PIN);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read the current GPIO state
        current_state = gpiod_line_get_value(GPIO_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error: Could not get GPIO %d value\n", GPIO_PIN);
            break; // Exit loop on error
        }

        // Check if the GPIO is currently in the desired state
        if (current_state == 1) {
            // Output is already set to 1, no need to set it again
            break;
        }

        // Set the GPIO pin to the desired state
        if (set_gpio_output(GPIO_PIN, 1) < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d to 1\n", GPIO_PIN);
            break;
        }

        // Wait for 0.001 seconds
        sleep(0.001);
    }

    // Clean up GPIO line
    if (set_gpio_output(GPIO_PIN, 0) < 0) {
        fprintf(stderr, "Error: Could not set GPIO %d to 0\n", GPIO_PIN);
    }

    // Release GPIO line
    gpiod_line_release(GPIO_PIN);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>
#include <string.h>

// Define GPIO pins
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3

// Define GPIO values
#define GPIO_VALUE_HIGH 1
#define GPIO_VALUE_LOW 0

// Define GPIO mode
#define GPIO_MODE_OUTPUT 0

// Define GPIO direction
#define GPIO_DIRECTION_OUTPUT 0

// Global variable to track program state
volatile sig_atomic_t program_running = 1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);
int gpio_get_value(int pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Function to export a GPIO pin
int gpio_export(int pin) {
    struct gpiod_export_request *request = malloc(sizeof(struct gpiod_export_request));
    if (!request) {
        perror("Failed to allocate memory for gpio_export_request");
        return -1;
    }

    request->type = GPID_EXPORT_LINE;
    request->line = pin;

    int ret = gpiod_export(request);
    free(request);
    return ret;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    struct gpiod_unexport_request *request = malloc(sizeof(struct gpiod_unexport_request));
    if (!request) {
        perror("Failed to allocate memory for gpio_unexport_request");
        return -1;
    }

    request->type = GPID_UNEXPORT_LINE;
    request->line = pin;

    int ret = gpiod_unexport(request);
    free(request);
    return ret;
}

// Function to set the direction of a GPIO pin
int gpio_set_direction(int pin, const char *direction) {
    struct gpiod_line_request *request = malloc(sizeof(struct gpiod_line_request));
    if (!request) {
        perror("Failed to allocate memory for gpio_set_direction_request");
        return -1;
    }

    request->type = GPID_LINE;
    request->line = pin;
    request->direction = direction;

    int ret = gpiod_set_direction(request);
    free(request);
    return ret;
}

// Function to set the value of a GPIO pin
int gpio_set_value(int pin, int value) {
    struct gpiod_line_request *request = malloc(sizeof(struct gpiod_line_request));
    if (!request) {
        perror("Failed to allocate memory for gpio_set_value_request");
        return -1;
    }

    request->type = GPID_LINE;
    request->line = pin;
    request->value = value;

    int ret = gpiod_set_value(request);
    free(request);
    return ret;
}

// Function to get the value of a GPIO pin
int gpio_get_value(int pin) {
    struct gpiod_value_request *request = malloc(sizeof(struct gpiod_value_request));
    if (!request) {
        perror("Failed to allocate memory for gpio_get_value_request");
        return -1;
    }

    request->type = GPID_VALUE;
    request->line = pin;

    int ret = gpiod_get_value(request);
    free(request);
    return ret;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Export GPIO pins
    if (gpio_export(GPIO_PIN_1) < 0 || gpio_export(GPIO_PIN_2) < 0) {
        fprintf(stderr, "Failed to export GPIO pins\n");
        gpiod_close();
        return 1;
    }

    // Set GPIO directions
    if (gpio_set_direction(GPIO_PIN_1, "out") < 0 || gpio_set_direction(GPIO_PIN_2, "out") < 0) {
        fprintf(stderr, "Failed to set GPIO directions\n");
        gpio_unexport(GPIO_PIN_1);
        gpio_unexport(GPIO_PIN_2);
        gpiod_close();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read GPIO values
        int value1 = gpio_get_value(GPIO_PIN_1);
        int value2 = gpio_get_value(GPIO_PIN_2);

        // Validate GPIO values
        if (value1 < 0 || value1 > 1 || value2 < 0 || value2 > 1) {
            fprintf(stderr, "Invalid GPIO value read. Exiting.\n");
            break;
        }

        // Check if GPIO 1 is high
        if (value1 == GPIO_VALUE_HIGH) {
            printf("GPIO 1: %d\n", value1);
        }

        // Check if GPIO 2 is high
        if (value2 == GPIO_VALUE_HIGH) {
            printf("GPIO 2: %d\n", value2);
        }

        // Delay for 5 seconds
        sleep(5);
    }

    // Unexport GPIO pins
    gpio_unexport(GPIO_PIN_1);
    gpio_unexport(GPIO_PIN_2);

    // Close libgpiod
    gpiod_close();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pin and mode
#define GPIO_PIN 23
#define GPIO_MODE GPIOD_OUTPUT

// Global variable to track program state
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to set the GPIO pin output state
int set_gpio_output(int pin, int value) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_line_get(pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", pin);
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO %d value to %d\n", pin, value);
        gpiod_line_release(line);
        return -1;
    }

    printf("GPIO %d set to %d\n", pin, value);
    return 0;
}

int main() {
    int ret;
    int current_state;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize libgpiod
    if (gpiod_line_request_output(GPIO_PIN, GPIO_MODE, 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d output\n", GPIO_PIN);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read the current GPIO state
        current_state = gpiod_line_get_value(GPIO_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error: Could not get GPIO %d value\n", GPIO_PIN);
            break; // Exit loop on error
        }

        // Check if the GPIO is currently set to the desired state
        if (current_state == 1) {
            // Set the GPIO pin to the desired state
            if (set_gpio_output(GPIO_PIN, 1) < 0) {
                fprintf(stderr, "Error: Could not set GPIO %d to 1\n", GPIO_PIN);
                break; // Exit loop on error
            }
        } else {
            // Set the GPIO pin to the current state
            if (set_gpio_output(GPIO_PIN, current_state) < 0) {
                fprintf(stderr, "Error: Could not set GPIO %d to %d\n", GPIO_PIN, current_state);
                break; // Exit loop on error
            }
        }

        // Delay to avoid overwhelming the system
        usleep(100000); // 100ms
    }

    // Release the GPIO pin
    if (set_gpio_output(GPIO_PIN, 0) < 0) {
        fprintf(stderr, "Error: Could not set GPIO %d to 0\n", GPIO_PIN);
    }

    // Release the GPIO line
    gpiod_line_release(GPIO_PIN);

    return 0;
}

