#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3

// Define GPIO numbering
#define GPIO_NUMBER_1 1
#define GPIO_NUMBER_2 2

// Global variable to track GPIO state
int gpio_state_1 = 0;
int gpio_state_2 = 0;

// Function prototypes
int gpio_export(int gpio);
int gpio_unexport(int gpio);
int gpio_set_direction(int gpio, const char *direction);
int gpio_write(int gpio, int value);
int gpio_read(int gpio);
int gpio_get_value(int gpio);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpio_unexport(GPIO_PIN_1);
    gpio_unexport(GPIO_PIN_2);
    exit(0);
}

// Function to export a GPIO pin
int gpio_export(int gpio) {
    struct gpiod_export_request *request = malloc(sizeof(struct gpiod_export_request));
    if (!request) {
        perror("Failed to allocate memory for gpio_export_request");
        return -1;
    }

    request->gpio = gpio;
    request->direction = "out"; // Set direction to output

    int ret = gpiod_export(request);
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIO %d: %s\n", gpio, strerror(errno));
        free(request);
        return -1;
    }

    printf("GPIO %d exported successfully.\n", gpio);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int gpio) {
    int ret = gpiod_unexport(gpio);
    if (ret < 0) {
        fprintf(stderr, "Failed to unexport GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    printf("GPIO %d unexported successfully.\n", gpio);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int gpio, const char *direction) {
    int ret = gpiod_set_direction(gpio, direction);
    if (ret < 0) {
        fprintf(stderr, "Failed to set direction for GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    printf("GPIO %d set direction to %s\n", gpio, direction);
    return 0;
}

// Function to write a value to a GPIO pin
int gpio_write(int gpio, int value) {
    int ret = gpiod_write(gpio, value);
    if (ret < 0) {
        fprintf(stderr, "Failed to write value to GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    printf("GPIO %d set to value %d\n", gpio, value);
    return 0;
}

