                close(fd);
                return 1;
            }
        } else if (bytes_read > 0) {
            // Print the received data
            printf("Received: %s\n", buffer);
        }

        // Write to the serial port
        bytes_written = write(fd, buffer, bytes_read);
        if (bytes_written == -1) {
            perror("Error writing to serial port");
            close(fd);
            return 1;
        }
    }

    // Cleanup
    close(fd);
    printf("Serial port closed.\n");
    return 0;
}

