// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 register addresses
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCtrl+C pressed. Exiting gracefully...\n");
}

// Function to read a 16-bit value from the ADXL345
int16_t read_register(int reg) {
    int16_t value = i2cReadWordData(i2c_handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return 0; // Return 0 on error
    }
    return value;
}

// Function to write a 16-bit value to the ADXL345
int write_register(int reg, int16_t value) {
    int result = i2cWriteWordData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1; // Return -1 on error
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0); // Bus 1, address 0x53, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Configure ADXL345 (ODR = 100 Hz, data format = +/- 2g, enable measurement)
    if (write_register(ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error configuring ADXL345\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read data from registers
        int16_t x = read_register(ADXL345_REG_DATAX0);
        int16_t y = read_register(ADXL345_REG_DATAY0);
        int16_t z = read_register(ADXL345_REG_DATAZ0);

        // Check for errors during reading
        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            continue; // Skip to the next iteration
        }

        // Print the raw values
        printf("X: %d, Y: %d, Z: %d\n", x, y, z);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

