    if (fd < 0) {
        perror("Failed to export GPIO");
        free(request);
        return -1;
    }

    return fd;
}

// Unexports a GPIO pin
int gpio_unexport(int gpio) {
    int fd = gpiod_unexport(gpio);
    if (fd < 0) {
        perror("Failed to unexport GPIO");
        return -1;
    }
    return fd;
}

// Sets the direction of a GPIO pin (in or out)
int gpio_set_direction(int gpio, const char *direction) {
    int fd = gpiod_get_direction(gpio);
    if (fd < 0) {
        perror("Failed to get direction for GPIO");
        return -1;
    }

    int ret = gpiod_set_direction(gpio, direction);
    if (ret < 0) {
        perror("Failed to set direction for GPIO");
        return -1;
    }

    return fd;
}

// Writes a value to a GPIO pin
int gpio_write(int gpio, int value) {
    int fd = gpiod_get_value(gpio);
    if (fd < 0) {
        perror("Failed to get value for GPIO");
        return -1;
    }

    int ret = gpiod_set_value(gpio, value);
    if (ret < 0) {
        perror("Failed to set value for GPIO");
        return -1;
    }

    return fd;
}

// Reads the value of a GPIO pin
int gpio_read(int gpio) {
    int fd = gpiod_get_value(gpio);
    if (fd < 0) {
        perror("Failed to get value for GPIO");
        return -1;
    }

    int ret = gpiod_get_value(gpio);
    if (ret < 0) {
        perror("Failed to get value for GPIO");
        return -1;
    }

    return ret;
}

