        gpio_export(GPIO_22) < 0) {
        fprintf(stderr, "Failed to export GPIO pins. Exiting.\n");
        return 1;
    }

    // Set GPIO directions
    if (gpio_set_direction(GPIO_18, "out") < 0 ||
        gpio_set_direction(GPIO_21, "out") < 0 ||
        gpio_set_direction(GPIO_22, "out") < 0) {
        fprintf(stderr, "Failed to set GPIO directions. Exiting.\n");
        gpio_unexport(GPIO_18);
        gpio_unexport(GPIO_21);
        gpio_unexport(GPIO_22);
        return 1;
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int value = gpio_read(GPIO_18);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO 18. Continuing.\n");
            continue; // Continue to the next iteration
        }

        if (value == 0) {
            gpio_write(GPIO_18, 1);
            gpio_write(GPIO_21, 0);
            gpio_write(GPIO_22, 0);
            printf("GPIO 18: High\n");
        } else if (value == 1) {
            gpio_write(GPIO_18, 0);
            gpio_write(GPIO_21, 1);
            gpio_write(GPIO_22, 0);
            printf("GPIO 18: Low\n");
        } else {
            fprintf(stderr, "Invalid GPIO value. Continuing.\n");
        }

        usleep(100000); // 100ms delay
    }

    // Unexport GPIO pins on exit
    gpio_unexport(GPIO_18);
    gpio_unexport(GPIO_21);
    gpio_unexport(GPIO_22);

    return 0;
}

