#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>
#include <string.h>

// Define GPIO pins
#define GPIO_22 22
#define GPIO_27 27

// Define GPIO device names
#define GPIO_DEVICE_1 "/dev/gpiochip0"
#define GPIO_DEVICE_2 "/dev/gpiochip1"

// Global variable to track program state
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize a GPIO pin
int initialize_gpio(int gpio_pin) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_line_get(gpio_pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_request_output(line, "my_app", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request output for GPIO %d: %s\n", gpio_pin, strerror(ret));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to set the GPIO pin state
int set_gpio_state(int gpio_pin, int state) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_line_get(gpio_pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO %d to %d: %s\n", gpio_pin, state, strerror(ret));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to report the GPIO state
void report_gpio_state(int gpio_pin) {
    int state = gpiod_line_get_value(gpiod_line_get(gpio_pin));
    if (state < 0) {
        fprintf(stderr, "Error: Could not get GPIO %d value\n", gpio_pin);
        return;
    }

    printf("GPIO %d: %d\n", gpio_pin, state);
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio(GPIO_22) < 0 || initialize_gpio(GPIO_27) < 0) {
        fprintf(stderr, "Error: GPIO initialization failed\n");
        return 1;
    }

    printf("GPIO pins initialized successfully.\n");

    // Main loop
    while (program_running) {
        // Set GPIO 22 to output
        if (set_gpio_state(GPIO_22, 1) < 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d to 1\n", GPIO_22);
        }

        // Set GPIO 27 to input
        if (set_gpio_state(GPIO_27, 0) < 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d to 0\n", GPIO_27);
        }

        // Wait for 0.01 seconds
        sleep(0.01);

        // Set GPIO 22 to input
        if (set_gpio_state(GPIO_22, 0) < 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d to 0\n", GPIO_22);
        }

        // Set GPIO 27 to output
        if (set_gpio_state(GPIO_27, 1) < 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d to 1\n", GPIO_27);
        }

        // Report GPIO state
        report_gpio_state(GPIO_22);
        report_gpio_state(GPIO_27);
    }

    // Cleanup GPIO pins before exiting
    set_gpio_state(GPIO_22, 0);
    set_gpio_state(GPIO_27, 0);

    return 0;
}

