#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>
#include <string.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_5 5

// Define GPIO device names
#define GPIO_DEVICE_1 "/dev/gpiochip0"
#define GPIO_DEVICE_2 "/dev/gpiochip1"

// Global variable to track program state
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio(int gpio_pin, int direction) {
    int fd;
    char buffer[64];

    fd = gpiod_export(gpio_pin, 0); // Export GPIO pin
    if (fd < 0) {
        fprintf(stderr, "Error exporting GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }

    // Set GPIO direction
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/direction", gpio_pin);
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO %d direction file: %s\n", gpio_pin, strerror(errno));
        gpiod_unexport(fd);
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        fprintf(stderr, "Error writing to GPIO %d direction file: %s\n", gpio_pin, strerror(errno));
        close(fd);
        gpiod_unexport(fd);
        return -1;
    }
    close(fd);

    return 0;
}

// Function to set GPIO value
int set_gpio_value(int gpio_pin, int value) {
    int fd;
    char buffer[64];

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/value", gpio_pin);
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO %d value file: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    if (write(fd, value, 1) < 0) {
        fprintf(stderr, "Error writing to GPIO %d value file: %s\n", gpio_pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to report GPIO state
void report_gpio_state(int gpio_pin) {
    char buffer[64];
    char value_str[3];
    int fd;

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/value", gpio_pin);
    fd = open(buffer, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO %d value file for reading: %s\n", gpio_pin, strerror(errno));
        return;
    }
    if (read(fd, value_str, 3) < 0) {
        fprintf(stderr, "Error reading GPIO %d value file: %s\n", gpio_pin, strerror(errno));
        close(fd);
        return;
    }
    close(fd);

    printf("GPIO %d: %s\n", gpio_pin, value_str);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio(GPIO_2, 0) < 0) {
        fprintf(stderr, "Failed to initialize GPIO 2\n");
        return 1;
    }
    if (initialize_gpio(GPIO_3, 0) < 0) {
        fprintf(stderr, "Failed to initialize GPIO 3\n");
        return 1;
    }
    if (initialize_gpio(GPIO_5, 0) < 0) {
        fprintf(stderr, "Failed to initialize GPIO 5\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set GPIO 2 to output
        if (set_gpio_value(GPIO_2, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO 2 value\n");
            break;
        }

        // Set GPIO 3 to output
        if (set_gpio_value(GPIO_3, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO 3 value\n");
            break;
        }

        // Set GPIO 5 to output
        if (set_gpio_value(GPIO_5, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO 5 value\n");
            break;
        }

        // Report GPIO state
        report_gpio_state(GPIO_2);
        report_gpio_state(GPIO_3);
        report_gpio_state(GPIO_5);

        // Delay for 5 seconds
        sleep(5);
    }

    // Cleanup GPIO pins
    set_gpio_value(GPIO_2, 0);
    set_gpio_value(GPIO_3, 0);
    set_gpio_value(GPIO_5, 0);

    return 0;
}

#include <stdio.h>
