#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Function prototypes
void signal_handler(int signal);
void pwm_set_duty_cycle(int gpio, int duty_cycle);

// Global variable to track program state
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as PWM output
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_4, PWM_RANGE);

    // Set PWM duty cycle
    pwm_set_duty_cycle(PWM_PIN_1, 0);
    pwm_set_duty_cycle(PWM_PIN_2, 0);
    pwm_set_duty_cycle(PWM_PIN_3, 0);
    pwm_set_duty_cycle(PWM_PIN_4, 0);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycles
        pwm_set_duty_cycle(PWM_PIN_1, 100);
        pwm_set_duty_cycle(PWM_PIN_2, 100);
        pwm_set_duty_cycle(PWM_PIN_3, 100);
        pwm_set_duty_cycle(PWM_PIN_4, 100);

        // Delay for 1 second
        gpioDelay(1000);
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
}

// Function to set PWM duty cycle
void pwm_set_duty_cycle(int gpio, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return;
    }

    // Calculate PWM pulse width (duty cycle is percentage of PWM range)
    int pulse_width = (int)(duty_cycle * PWM_RANGE / 100.0);

    // Set PWM range
    gpioPWM(gpio, PWM_RANGE);

    // Set PWM frequency
    gpioSetPWMfrequency(gpio, PWM_FREQUENCY);

    // Set PWM duty cycle
    gpioPWM(gpio, PWM_PIN_1);
    gpioPWM(gpio, PWM_PIN_2);
    gpioPWM(gpio, PWM_PIN_3);
    gpioPWM(gpio, PWM_PIN_4);

    // Delay for 1 microsecond
    gpioDelay(1);
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 23
#define ECHO_PIN_2 24
#define ECHO_PIN_3 25

// Define pulse width range
#define PULSE_WIDTH_MIN 10
#define PULSE_WIDTH_MAX 2000

// Define timeout in microseconds
#define TIMEOUT_US 1000000

// Global variable to track program state
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to trigger the HC-SR04
int trigger_hc_sr04(int trigger_pin, int echo_pin) {
    gpioWrite(trigger_pin, 1);
    usleep(10); // 10us trigger pulse
    gpioWrite(trigger_pin, 0);
    usleep(2); // 2us echo pulse
    return gpioRead(echo_pin);
}

// Function to measure the distance
int measure_distance(int echo_pin) {
    long start_time, end_time;
    long pulse_width;

    // Wait for the echo pin to go high
    while (gpioRead(echo_pin) == 0) {
        usleep(1); // Wait for echo to go high
    }

    start_time = time_time();

    // Wait for the echo pin to go low
    while (gpioRead(echo_pin) == 1) {
        usleep(1); // Wait for echo to go low
    }

    end_time = time_time();

    pulse_width = end_time - start_time;

    // Calculate the distance in centimeters
    if (pulse_width < PULSE_WIDTH_MIN) {
        pulse_width = PULSE_WIDTH_MIN;
    } else if (pulse_width > PULSE_WIDTH_MAX) {
        pulse_width = PULSE_WIDTH_MAX;
    }

    return (int)(pulse_width * 0.0343 / 2); // Convert microseconds to centimeters
}

// Function to check if the distance is within the specified range
int is_within_range(int distance, int min_range, int max_range) {
    return (distance >= min_range && distance <= max_range);
}

// Function to log the distance with timestamp
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Distance: %d cm\n", timestamp, distance);
}

int main() {
    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "libgpiod initialization failed\n");
        return 1;
    }

