        gpiod_unexport(ECHO_PIN_2);
        gpiod_unexport(ECHO_PIN_3);
        gpiod_close();
        return 1;
    }
    if (gpiod_set_mode(ECHO_PIN_2, GPIOD_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin 2 mode\n");
        gpiod_unexport(TRIGGER_PIN);
        gpiod_unexport(ECHO_PIN);
        gpiod_unexport(ECHO_PIN_3);
        gpiod_close();
        return 1;
