    gpioSetMode(STRIP_PIN_10, PI_OUTPUT);
    gpioSetMode(STRIP_PIN_11, PI_OUTPUT);
    gpioSetMode(STRIP_PIN_12, PI_OUTPUT);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Set the color of each pixel
        for (int i = 0; i < NUM_PIXELS; i++) {
            set_pixel_color(STRIP_PIN_1, colors[i][0]);
            set_pixel_color(STRIP_PIN_2, colors[i][1]);
            set_pixel_color(STRIP_PIN_3, colors[i][2]);
            set_pixel_color(STRIP_PIN_4, colors[i][0]);
            set_pixel_color(STRIP_PIN_5, colors[i][1]);
            set_pixel_color(STRIP_PIN_6, colors[i][2]);
            set_pixel_color(STRIP_PIN_7, colors[i][0]);
            set_pixel_color(STRIP_PIN_8, colors[i][1]);
            set_pixel_color(STRIP_PIN_9, colors[i][2]);
            set_pixel_color(STRIP_PIN_10, colors[i][0]);
            set_pixel_color(STRIP_PIN_11, colors[i][1]);
            set_pixel_color(STRIP_PIN_12, colors[i][2]);
        }

        // Delay for 0.01 seconds
        gpioDelay(10000); // 10 milliseconds
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

