// Function to initialize a GPIO pin
int initialize_gpio(int gpio_pin) {
    struct gpiod_line *line;
    int ret;

    // Open the GPIO line
    line = gpiod_line_open(gpio_pin, 0);
    if (!line) {
        fprintf(stderr, "Error opening GPIO line %d: %s\n", gpio_pin, gpiod_error_to_str(gpiod_error_to_str(line)));
        return -1;
    }

    // Set the GPIO direction to output
    ret = gpiod_line_set_direction(line, GPIOD_DIRECTION_OUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO direction for pin %d: %s\n", gpio_pin, gpiod_error_to_str(ret));
        gpiod_line_close(line);
        return -1;
    }

    // Export the GPIO pin
    ret = gpiod_export(gpio_pin, 0);
    if (ret < 0) {
        fprintf(stderr, "Error exporting GPIO pin %d: %s\n", gpio_pin, gpiod_error_to_str(ret));
        gpiod_line_close(line);
        return -1;
    }

    return 0;
}

// Function to unexport a GPIO pin
int unexport_gpio(int gpio_pin) {
    int ret;
    ret = gpiod_unexport(gpio_pin);
    if (ret < 0) {
        fprintf(stderr, "Error unexporting GPIO pin %d: %s\n", gpio_pin, gpiod_error_to_str(ret));
        return -1;
    }
    return 0;
}

// Function to set the GPIO output value
int set_gpio_output(int gpio_pin, int value) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_line_open(gpio_pin, 0);
    if (!line) {
        fprintf(stderr, "Error opening GPIO line %d: %s\n", gpio_pin, gpiod_error_to_str(gpiod_error_to_str(line)));
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value for pin %d: %s\n", gpio_pin, gpiod_error_to_str(ret));
        gpiod_line_close(line);
        return -1;
    }

    gpiod_line_close(line);
    return 0;
}

// Function to report the GPIO state
void report_gpio_state(int gpio_pin) {
    int ret;
    char buffer[50];
    char *state_str;

    // Open the GPIO line
    ret = gpiod_line_open(gpio_pin, 0);
    if (!ret) {
        fprintf(stderr, "Error opening GPIO line %d: %s\n", gpio_pin, gpiod_error_to_str(ret));
        return;
    }

    // Get the GPIO value
    state_str = gpiod_line_get_value(ret);
    if (!state_str) {
        fprintf(stderr, "Error getting GPIO value for pin %d: %s\n", gpio_pin, gpiod_error_to_str(ret));
        gpiod_line_close(ret);
        return;
    }

    // Format the state string
    snprintf(buffer, sizeof(buffer), "%s", state_str);

    // Print the state
    printf("GPIO %d: %s\n", gpio_pin, buffer);

    // Close the GPIO line
    gpiod_line_close(ret);
}

