#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pin and GPIO mode
#define GPIO_PIN 17
#define GPIO_MODE GPIOD_INPUT

// Global variable to track GPIO state
volatile int gpio_state = 0;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
int gpio_write(int pin, int value);
int gpio_get_value(int pin);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpio_unexport(GPIO_PIN);
    exit(0);
}

// Exports the specified GPIO pin
int gpio_export(int pin) {
    struct gpiod_export_request *request = malloc(sizeof(struct gpiod_export_request));
    if (!request) {
        perror("Failed to allocate memory for gpio_export_request");
        return -1;
    }

    request->gpio = pin;
    request->flags = 0; // No flags for now

    int fd = gpiod_export(request);
    if (fd < 0) {
        perror("Failed to export GPIO");
        free(request);
        return -1;
    }

    return fd;
}

// Unexports the specified GPIO pin
int gpio_unexport(int pin) {
    int fd = gpiod_unexport(pin);
    if (fd < 0) {
        perror("Failed to unexport GPIO");
        return -1;
    }
    return fd;
}

// Sets the direction of the specified GPIO pin (input or output)
int gpio_set_direction(int pin, const char *direction) {
    int fd = gpiod_get_direction(pin);
    if (fd < 0) {
        perror("Failed to get direction of GPIO");
        return -1;
    }

    int ret = gpiod_set_direction(pin, direction);
    if (ret < 0) {
        perror("Failed to set direction of GPIO");
        return -1;
    }
    return fd;
}

// Reads the value of the specified GPIO pin
int gpio_read(int pin) {
    int fd = gpiod_get_value(pin);
    if (fd < 0) {
        perror("Failed to get value of GPIO");
        return -1;
    }
    return fd;
}

// Writes the specified value to the specified GPIO pin
int gpio_write(int pin, int value) {
    int fd = gpiod_set_value(pin, value);
    if (fd < 0) {
        perror("Failed to set value of GPIO");
        return -1;
    }
    return fd;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Export the GPIO pin
    int fd = gpio_export(GPIO_PIN);
    if (fd < 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        return 1;
    }

    // Set the GPIO direction to input
    if (gpio_set_direction(GPIO_PIN, "in") < 0) {
        fprintf(stderr, "Failed to set direction of GPIO %d\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    printf("GPIO %d initialized and set to input.  Reading...\n", GPIO_PIN);

    // Main loop to read and print the GPIO value
    while (1) {
        int value = gpio_read(GPIO_PIN);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", GPIO_PIN);
            break; // Exit loop on error
        }

        printf("GPIO %d: %d\n", GPIO_PIN, value);

        // Delay to avoid overwhelming the system
        usleep(100000); // 100ms
    }

    // Unexport the GPIO pin before exiting
    gpio_unexport(GPIO_PIN);

    return 0;
}

