// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Function to export a GPIO pin
int gpio_export(int gpio) {
    struct gpiod_export_request *request = malloc(sizeof(struct gpiod_export_request));
    if (!request) {
        fprintf(stderr, "Error: Failed to allocate memory for gpio_export_request\n");
        return -1;
    }

    request->gpio = gpio;
    request->flags = 0; // No flags for now

    int ret = gpiod_export(request);
    free(request);
    return ret;
}

// Function to unexport a GPIO pin
int gpio_unexport(int gpio) {
    struct gpiod_unexport_request *request = malloc(sizeof(struct gpiod_unexport_request));
    if (!request) {
        fprintf(stderr, "Error: Failed to allocate memory for gpio_unexport_request\n");
        return -1;
    }

    request->gpio = gpio;
    request->flags = 0; // No flags for now

    int ret = gpiod_unexport(request);
    free(request);
    return ret;
}

// Function to set the direction of a GPIO pin (input or output)
int gpio_set_direction(int gpio, const char *direction) {
    struct gpiod_direction_request *request = malloc(sizeof(struct gpiod_direction_request));
    if (!request) {
        fprintf(stderr, "Error: Failed to allocate memory for gpio_set_direction_request\n");
        return -1;
    }

    request->gpio = gpio;
    request->direction = strdup(direction);
    if (!request->direction) {
        fprintf(stderr, "Error: Failed to allocate memory for strdup\n");
        free(request);
        return -1;
    }

    int ret = gpiod_set_direction(request);
    free(request->direction);
    free(request);
    return ret;
}

// Function to write a value to a GPIO pin
int gpio_write(int gpio, int value) {
    struct gpiod_value_request *request = malloc(sizeof(struct gpiod_value_request));
    if (!request) {
        fprintf(stderr, "Error: Failed to allocate memory for gpio_write_request\n");
        return -1;
    }

    request->gpio = gpio;
    request->value = value;

    int ret = gpiod_set_value(request);
    free(request->value);
    free(request);
    return ret;
}

// Function to read the value of a GPIO pin
int gpio_read(int gpio) {
    struct gpiod_value_request *request = malloc(sizeof(struct gpiod_value_request));
    if (!request) {
        fprintf(stderr, "Error: Failed to allocate memory for gpio_read_request\n");
        return -1;
    }

    request->gpio = gpio;

    int ret = gpiod_get_value(request);
    free(request->value);
    free(request);
    return ret;
}

