#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_PRESSURE_MSB 0xF7
#define BME280_REG_HUMIDITY_MSB 0xFD
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_ID 0xD0

// Calibration data registers
#define BME280_REG_CALIB_00 0x88

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Structure to hold calibration data
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
} bme280_calib_data;

bme280_calib_data calib;

// Function prototypes
int bme280_init(int i2c_handle);
int bme280_read_calibration_data(int i2c_handle, bme280_calib_data *calib);
int bme280_read_raw_data(int i2c_handle, int32_t *temperature, int32_t *pressure, int32_t *humidity);
double bme280_compensate_temperature(int32_t raw_temperature, const bme280_calib_data *calib);
double bme280_compensate_pressure(int32_t raw_pressure, int32_t raw_temperature, const bme280_calib_data *calib);
double bme280_compensate_humidity(int32_t raw_humidity, const bme280_calib_data *calib);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the BME280 sensor
int bme280_init(int i2c_handle) {
    // Check the device ID
    int id = i2c_read_byte_data(i2c_handle, BME280_REG_ID);
    if (id != 0x60) {
        fprintf(stderr, "Error: BME280 not found at address 0x%02x (0x%x)\n", BME280_I2C_ADDR, id);
        return -1;
    }

    // Read calibration data
    if (bme280_read_calibration_data(i2c_handle, &calib) != 0) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }

    // Set humidity oversampling to 1x
    if (i2c_write_byte_data(i2c_handle, BME280_REG_CTRL_HUM, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to set humidity oversampling\n");
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and normal mode
    if (i2c_write_byte_data(i2c_handle, BME280_REG_CTRL_MEAS, 0x25) != 0) {
        fprintf(stderr, "Error: Failed to set control register\n");
        return -1;
    }

    // Set humidity oversampling to 1x
    if (i2c_write_byte_data(i2c_handle, BME280_REG_CTRL_HUM, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to set humidity oversampling\n");
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and normal mode
    if (i2c_write_byte_data(i2c_handle, BME280_REG_CTRL_MEAS, 0x25) != 0) {
        fprintf(stderr, "Error: Failed to set control register\n");
        return -1;
    }

    return 0;
}

// Read calibration data from the BME280
int bme280_read_calibration_data(int i2c_handle, bme280_calib_data *calib) {
    calib->dig_T1 = i2c_read_word_data(i2c_handle, BME280_REG_CALIB_00);
    calib->dig_T2 = i2c_read_word_data(i2c_handle, BME280_REG_CALIB_00 + 2);
    calib->dig_T3 = i2c_read_word_data(i2c_handle, BME280_REG_CALIB_00 + 4);
    calib->dig_P1 = i2c_read_word_data(i2c_handle, BME280_REG_CALIB_00 + 6);
    calib->dig_P2 = i2c_read_word_data(i2c_handle, BME280_REG_CALIB_00 + 8);
    calib->dig_P3 = i2c_read_word_data(i2c_handle, BME280_REG_CALIB_00 + 10);
    calib->dig_P4 = i2c_read_word_data(i2c_handle, BME280_REG_CALIB_00 + 12);
    calib->dig_P5 = i2c_read_word_data(i2c_handle, BME280_REG_CALIB_00 + 14);
    calib->dig_P6 = i2c_read_word_data(i2c_handle, BME280_REG_CALIB_00 + 16);
    calib->dig_P7 = i2c_read_word_data(i2c_handle, BME280_REG_CALIB_00 + 18);
    calib->dig_P8 = i2c_read_word_data(i2c_handle, BME280_REG_CALIB_00 + 20);
    calib->dig_P9 = i2c_read_word_data(i2c_handle, BME280_REG_CALIB_00 + 22);
    calib->dig_H1 = i2c_read_byte_data(i2c_handle, BME280_REG_CALIB_00 + 23);
    calib->dig_H2 = i2c_read_word_data(i2c_handle, BME280_REG_CALIB_00 + 25);
    calib->dig_H3 = i2c_read_byte_data(i2c_handle, BME280_REG_CALIB_00 + 26);
    calib->dig_H4 = i2c_read_word_data(i2c_handle, BME280_REG_CALIB_00 + 28);
    calib->dig_H5 = i2c_read_word_data(i2c_handle, BME280_REG_CALIB_00 + 30);
    calib->dig_H6 = i2c_read_byte_data(i2c_handle, BME280_REG_CALIB_00 + 31);

    return 0;
}

// Read raw temperature, pressure, and humidity data from the BME280
int bme280_read_raw_data(int i2c_handle, int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    // Read raw data
    int32_t raw_pressure = i2c_read_word_data(i2c_handle, BME280_REG_PRESSURE_MSB);
    int32_t raw_temperature = i2c_read_word_data(i2c_handle, BME280_REG_TEMP_MSB);
    int32_t raw_humidity = i2c_read_word_data(i2c_handle, BME280_REG_HUMIDITY_MSB);

    if (raw_pressure == 0xFFFF || raw_temperature == 0xFFFF || raw_humidity == 0xFFFF) {
        fprintf(stderr, "Error: I2C read error\n");
        return -1;
    }

    // Compensate temperature
    *temperature = bme280_compensate_temperature(raw_temperature, &calib);
    *pressure = bme280_compensate_pressure(raw_pressure, *temperature, &calib);
    *humidity = bme280_compensate_humidity(raw_humidity, &calib);

    return 0;
}

// Compensate temperature
double bme280_compensate_temperature(int32_t raw_temperature, const bme280_calib_data *calib) {
    double var1, var2, T;
    var1 = (((double)raw_temperature / 16384.0) - ((double)calib->dig_T1) / 1024.0) * ((double)calib->dig_T2);
    var2 = ((((double)raw_temperature / 131072.0) - ((double)calib->dig_T1) / 8192.0) * (((double)raw_temperature / 131072.0) - ((double)calib->dig_T1) / 8192.0)) * ((double)calib->dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure
double bme280_compensate_pressure(int32_t raw_pressure, int32_t raw_temperature, const bme280_calib_data *calib) {
    double var1, var2, p;
    var1 = ((double)raw_temperature / 16384.0) - ((double)calib->dig_T1) / 1024.0;
    var2 = ((var1 * var1) / 52429.0) - ((double)calib->dig_T2) / 524288.0;
    var2 = (var2 / 524288.0) * ((double)calib->dig_T3);
    double t_fine = var1 + var2;
    double var3 = ((double)t_fine / 2.0) - 64000.0;
    var1 = (((double)calib->dig_P6) * var1 * var1 / 2147483648.0) + (((double)calib->dig_P5) * var1) / 32768.0;
    var2 = (((double)calib->dig_P4) * var1 / 2147483648.0) + (((double)calib->dig_P3) * 65536.0);
    var1 = (var1 + var2) / 16384.0;
    var2 = ((double)calib->dig_P2) * var1 * var1 / 2147483648.0 + ((double)calib->dig_P1) * var1 / 32768.0;
    var1 = (var1 + var2) / 16384.0;
    var2 = ((double)calib->dig_P9) * var1 * var1 / 2147483648.0 + ((double)calib->dig_P8) * var1 / 32768.0;
    var1 = (var1 + var2) / 16384.0;
    var2 = ((double)calib->dig_P7) * var1 / 2147483648.0;
    p = 1048576.0 - raw_pressure;
    p = (p - (var1 * 65.0)) * (var3 / 4096.0);
    var1 = (((double)calib->dig_P4) * p * p / 2147483648.0) + (((double)calib->dig_P3) * p) / 32768.0;
    var2 = (((double)calib->dig_P2) * p / 32768.0) + ((double)calib->dig_P1) * 4.0;
    p = (p + (var1 + var2 + (double)calib->dig_P5) / 16.0);
    p = (p / 4.0) + (p / 1024.0);
    p = (p * 100.0) / (double)calib->dig_P6;
    if (p < 0) {
        p = 0;
    } else if (p > 1000000) {
        p = 1000000;
    }
    return p;
}

// Compensate humidity
double bme280_compensate_humidity(int32_t raw_humidity, const bme280_calib_data *calib) {
    double var_H;
    var_H = ((double)raw_humidity - ((double)calib->dig_H4) * 64.0 - ((double)calib->dig_H5) / 16384.0 * ((double)raw_humidity - ((double)calib->dig_H4) * 64.0 - ((double)calib->dig_H6) / 131072.0 * ((double)raw_humidity - ((double)calib->dig_H4) * 64.0 - ((double)calib->dig_H6) / 131072.0 * ((double)calib->dig_H5) / 524288.0));
    var_H = var_H * (1.0 - ((double)calib->dig_H2) / 131072.0);
    if (var_H > 100.0)
        var_H = 100.0;
    else if (var_H < 0.0)
        var_H = 0.0;
    return var_H;
}

