// Configuration
#define MQTT_BROKER_ADDRESS "localhost" // Replace with your broker address
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "rpi_sensor_reader"
#define MQTT_RETAIN "false"
#define MQTT_QOS 1
#define MQTT_KEEPALIVE_INTERVAL 60 // seconds
#define MQTT_KEEPALIVE_RETAIN 60 // seconds
#define MQTT_CONNECT_TIMEOUT 5 // seconds
#define MQTT_PUBLISH_INTERVAL 0.01 // seconds

// Global variables
static int mqtt_client = -1;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_mqtt();
int publish_sensor_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold MQTT client data
typedef struct {
    int client_id;
    int connect_count;
} mqtt_client_t;

// Function to initialize the MQTT client
int initialize_mqtt() {
    mqtt_client_t client = {
        .client_id = MQTT_CLIENT_ID,
        .connect_count = 0
    };

    int retries = 3;
    int result = -1;

    while (retries > 0) {
        result = mosquitto_create_client(
            &client.mqtt_client,
            MQTT_BROKER_ADDRESS,
            MQTT_BROKER_PORT,
            false
        );

        if (result == MOSQ_ERR_SUCCESS) {
            mosquitto_connect_callback_set(&client);
            mosquitto_message_callback_set(&client, publish_sensor_data);
            mosquitto_loop_start(&client);
            client.connect_count++;
            printf("MQTT client connected successfully.\n");
            return 0;
        } else {
            fprintf(stderr, "MQTT connection failed: %s\n", mosquitto_strerror(result));
            retries--;
            gpioDelay(1000); // Wait before retrying
        }
    }

    fprintf(stderr, "MQTT connection failed after multiple retries.\n");
    return -1;
}

// Function to publish sensor data to MQTT
int publish_sensor_data(float temperature, float humidity) {
    struct mosquitto *mosq = NULL;
    struct mosquitto_message *message = NULL;
    char *payload = NULL;
    char *topic = NULL;
    int retries = 3;
    int result;

    // Create message
    payload = (char *)malloc(100 * sizeof(char));
    if (payload == NULL) {
        fprintf(stderr, "Failed to allocate memory for payload.\n");
        return -1;
    }
    snprintf(payload, 100, "{\"temperature\": %.2f, \"humidity\": %.2f}", temperature, humidity);

    topic = (char *)malloc(100 * sizeof(char));
    if (topic == NULL) {
        fprintf(stderr, "Failed to allocate memory for topic.\n");
        free(payload);
        return -1;
    }
    snprintf(topic, 100, "%s/%s", MQTT_TOPIC, MQTT_KEEPALIVE_INTERVAL);

    // Create MQTT client
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Failed to create MQTT client.\n");
        free(payload);
        free(topic);
        return -1;
    }

    // Connect to MQTT broker
    result = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, MQTT_CONNECT_TIMEOUT);
    if (result != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", mosquitto_strerror(result));
        mosquitto_destroy(mosq);
        free(payload);
        free(topic);
        return -1;
    }

    // Set MQTT message callback
    mosquitto_message_callback_set(&client, publish_sensor_data);

    // Connect callback
    mosquitto_connect_callback_set(&client, publish_sensor_data);

    // Connect loop
    while (retries > 0) {
        retries--;
        result = mosquitto_loop_start(mosq, MQTT_KEEPALIVE_INTERVAL, true);
        if (result == MOSQ_ERR_SUCCESS) {
            break;
        } else {
            fprintf(stderr, "MQTT loop failed: %s\n", mosquitto_strerror(result));
            mosquitto_disconnect(mosq, false);
            mosquitto_destroy(mosq);
            free(payload);
            free(topic);
            return -1;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to connect to MQTT broker after multiple retries.\n");
        mosquitto_destroy(mosq);
        free(payload);
        free(topic);
        return -1;
    }

    // Publish message
    message = mosquitto_message_new(mosq,
                                     NULL,
                                     payload,
                                     strlen(payload),
                                     MQTT_KEEPALIVE_INTERVAL,
                                     false,
                                     false);
    if (!message) {
        fprintf(stderr, "Failed to create MQTT message.\n");
        mosquitto_destroy(mosq);
        free(payload);
        free(topic);
        return -1;
    }

    result = mosquitto_publish(mosq,
                              NULL,
                              topic,
                              strlen(payload),
                              message,
                              0,
                              false);
    if (result != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to publish MQTT message: %s\n", mosquitto_strerror(result));
        mosquitto_destroy(mosq);
        free(payload);
        free(topic);
        return -1;
    }

    mosquitto_message_free(message);
    mosquitto_destroy(mosq);
    free(payload);
    free(topic);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    if (mqtt_client != -1) {
        mosquitto_disconnect(mqtt_client, false);
        mosquitto_destroy(mqtt_client);
        mqtt_client = -1;
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize MQTT client
    mqtt_client = initialize_mqtt();
    if (mqtt_client == -1) {
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        if (publish_sensor_data(temperature, humidity) == 0) {
            printf("Sensor data published successfully.\n");
        } else {
            fprintf(stderr, "Failed to publish sensor data.\n");
        }

        gpioDelay(MQTT_PUBLISH_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

