                break;
            }
        }

        usleep(50000); // Wait 50ms
    }

    // Cleanup: Release GPIO line
    if (set_gpio_value(GPIO_PIN, 0) < 0) {
        fprintf(stderr, "Error: Could not set GPIO %d low on exit\n", GPIO_PIN);
    }

    return 0;
}

