// Function to export a GPIO pin
int gpio_export(int gpio) {
    struct gpiod_export_request *request = malloc(sizeof(struct gpiod_export_request));
    if (!request) {
        perror("Failed to allocate memory for gpio_export_request");
        return -1;
    }

    request->gpio = gpio;
    request->flags = 0; // No flags for now

    int ret = gpiod_export(request);
    free(request);
    return ret;
}

// Function to unexport a GPIO pin
int gpio_unexport(int gpio) {
    struct gpiod_unexport_request *request = malloc(sizeof(struct gpiod_unexport_request));
    if (!request) {
        perror("Failed to allocate memory for gpio_unexport_request");
        return -1;
    }

    request->gpio = gpio;
    request->flags = 0; // No flags for now

    int ret = gpiod_unexport(request);
    free(request);
    return ret;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int gpio, const char *direction) {
    struct gpiod_direction_request *request = malloc(sizeof(struct gpiod_direction_request));
    if (!request) {
        perror("Failed to allocate memory for gpio_set_direction_request");
        return -1;
    }

    request->gpio = gpio;
    strncpy(request->direction, direction, sizeof(request->direction) - 1);
    request->direction[sizeof(request->direction) - 1] = '\0'; // Ensure null termination

    int ret = gpiod_set_direction(request);
    free(request);
    return ret;
}

// Function to write a value to a GPIO pin
int gpio_write(int gpio, int value) {
    struct gpiod_value_request *request = malloc(sizeof(struct gpiod_value_request));
    if (!request) {
        perror("Failed to allocate memory for gpio_write_request");
        return -1;
    }

    request->gpio = gpio;
    request->value = value;

    int ret = gpiod_set_value(request);
    free(request);
    return ret;
}

