    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("PWM control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Set PWM duty cycle
        if (set_pwm_duty_cycle(PWM_PIN, 50) != 0) {
            fprintf(stderr, "Error: Failed to set PWM duty cycle\n");
        }

        // Delay for 1 second
        gpioDelay(1000);
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

