// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24

// Define pulse width range
#define MIN_PULSE_WIDTH 10  // us
#define MAX_PULSE_WIDTH 2000 // us

// Global variable to track program state
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
int trigger_sensor() {
    struct gpiod_line *trigger_line = gpiod_line_get(TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Error: Could not get trigger line\n");
        return -1;
    }

    int ret = gpiod_line_set_value(trigger_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set trigger line %d to high\n", TRIGGER_PIN);
        gpiod_line_release(trigger_line);
        return -1;
    }

    usleep(2); // Wait for 2us

    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set trigger line %d to low\n", TRIGGER_PIN);
        gpiod_line_release(trigger_line);
        return -1;
    }

    return 0;
}

// Function to measure the pulse width
int measure_pulse_width() {
    struct gpiod_line *trigger_line = gpiod_line_get(TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Error: Could not get trigger line\n");
        return -1;
    }

    struct timespec start, end;
    int ret;

    // Wait for the trigger to go high
    ret = gpiod_line_get_value(trigger_line);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not get trigger line %d value\n", TRIGGER_PIN);
        gpiod_line_release(trigger_line);
        return -1;
    }
    if (ret == 0) {
        fprintf(stderr, "Error: Trigger line %d is already high\n", TRIGGER_PIN);
        gpiod_line_release(trigger_line);
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for the echo pin to go low
    ret = gpiod_line_get_value(ECHO_PIN);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not get echo line %d value\n", ECHO_PIN);
        gpiod_line_release(trigger_line);
        return -1;
    }
    if (ret == 1) {
        fprintf(stderr, "Error: Echo line %d is already low\n", ECHO_PIN);
        gpiod_line_release(trigger_line);
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate pulse width in nanoseconds
    long long pulse_width_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);

    // Check for overflow
    if (pulse_width_ns > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width exceeds maximum value (%lld)\n", MAX_PULSE_WIDTH);
        return -1;
    }

    return (int)pulse_width_ns;
}

// Function to convert pulse width to distance in centimeters
float convert_pulse_width_to_distance(int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Invalid pulse width: %d\n", pulse_width);
        return -1.0;
    }

    // Speed of sound in air: 343 m/s
    float speed_of_sound = 343.0 * 1000.0 / 2.0; // cm/us * 1 us/cm * 2
    return (float)pulse_width * speed_of_sound / 2.0;
}

