#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 17
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    signal(SIGINT, signal_handler);

    while (running) {
        int pwm_value = 0; // Initialize to 0
        if (gpioPWM(PWM_GPIO, pwm_value) != 0) {
            fprintf(stderr, "Failed to set PWM value\n");
            running = 0; // Exit loop if PWM set fails
            break;
        }

        printf("PWM value: %d\n", pwm_value);
        gpioDelay(100); // Delay for 100ms
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <time.h>
#include <sys/time.h>

// Configuration
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define DEVICE_ID "device1"
#define VALIDITY_CHECK_INTERVAL 5 // seconds
#define MAX_RETRIES 3

// Global variables
static int mqtt_client = -1;
static volatile int running = 1;

// Function prototypes
int initialize_mqtt();
int publish_sensor_data(const char *device_id, const char *sensor_data);
void signal_handler(int signal);
void cleanup();

// Structure for MQTT message
typedef struct {
    char *topic;
    char *payload;
} MQTTMessage;

// Function to initialize MQTT client
int initialize_mqtt() {
    mosquitto_lib_init();
    mqtt_client = mosquitto_create_client(NULL, true, NULL);
    if (!mqtt_client) {
        fprintf(stderr, "Error: Out of memory.\n");
        return -1;
    }

    mosquitto_connect_callback_set(mqtt_client, NULL);
    mosquitto_message_callback_set(mqtt_client, NULL);

    mosquitto_loop_start(mqtt_client);
    return 0;
}

// Function to publish sensor data to MQTT
int publish_sensor_data(const char *device_id, const char *sensor_data) {
    MQTTMessage message;
    message.topic = strdup(MQTT_TOPIC);
    if (!message.topic) {
        fprintf(stderr, "Error: Out of memory.\n");
        return -1;
    }
    message.payload = strdup(sensor_data);
    if (!message.payload) {
        fprintf(stderr, "Error: Out of memory.\n");
        free(message.topic);
        return -1;
    }

    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = mosquitto_publish(mqtt_client, message.topic, strlen(message.payload), message.payload, 0, false);
        if (result == MOSQ_ERR_SUCCESS) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: MQTT publish failed (attempt %d/%d), retrying...\n", retries + 1, MAX_RETRIES);
            sleep(1); // Wait before retrying
            retries++;
        }
    }

    fprintf(stderr, "Error: Failed to publish sensor data after %d retries.\n", MAX_RETRIES);
    free(message.topic);
    free(message.payload);
    return -1;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    if (mqtt_client != -1) {
        mosquitto_disconnect(mqtt_client);
        mosquitto_destroy_client(mqtt_client);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize MQTT
    if (initialize_mqtt() != 0) {
        cleanup();
        return 1;
    }

    printf("MQTT client initialized successfully.\n");

    // Main loop
    while (running) {
        // Get current timestamp
        struct timeval tv;
        gettimeofday(&tv, NULL);
        long timestamp = (long)tv.tv_sec * 1000000 + (long)tv.tv_usec;

        // Simulate sensor reading
        char *sensor_data = (char *)malloc(100 * sizeof(char)); // Allocate memory for sensor data
        if (!sensor_data) {
            fprintf(stderr, "Error: Out of memory.\n");
            cleanup();
            return 1;
        }
        snprintf(sensor_data, 100, "Timestamp: %ld, Sensor Data: %s", timestamp, "Sample Sensor Data");

        // Publish sensor data
        if (publish_sensor_data(DEVICE_ID, sensor_data) != 0) {
            fprintf(stderr, "Error: Failed to publish sensor data.\n");
        }

        sleep(VALIDITY_CHECK_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
