#include <unistd.h>

// Configuration
#define MQTT_BROKER_ADDRESS "localhost" // Change to your MQTT broker address
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "sensor/ads1115"
#define ADS1115_CHANNEL 0
#define NUM_READINGS 10

// Global variables
static int mqtt_client = -1;
static volatile int running = 1;

// Function prototypes
int init_mqtt(const char *broker_address, int broker_port);
int publish_reading(int channel, int16_t reading);
void signal_handler(int signal);

// Structure to hold MQTT client data
typedef struct {
    mosquitto_client_t *client;
} mqtt_client_t;

// Function to initialize the MQTT client
int init_mqtt(const char *broker_address, int broker_port) {
    mosquitto_lib_init();
    mqtt_client = (mqtt_client_t *)malloc(sizeof(mqtt_client_t));
    if (!mqtt_client) {
        fprintf(stderr, "Error: Failed to allocate memory for MQTT client.\n");
        return -1;
    }

    mqtt_client->client = mosquitto_new(NULL, true, NULL);
    if (!mqtt_client->client) {
        fprintf(stderr, "Error: Failed to create MQTT client instance.\n");
        free(mqtt_client);
        return -1;
    }

    int rc = mosquitto_connect(mqtt_client->client, broker_address, broker_port, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Failed to connect to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mqtt_client->client);
        free(mqtt_client);
        return -1;
    }

    mosquitto_loop_start(mqtt_client->client);
    return 0;
}

// Function to publish a reading to MQTT
int publish_reading(int channel, int16_t reading) {
    char message[64];
    snprintf(message, sizeof(message), "{\"channel\": %d, \"reading\": %d}", channel, reading);

    int rc = mosquitto_publish(mqtt_client->client, MQTT_TOPIC, strlen(message), message, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Failed to publish message to MQTT broker: %s\n", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize MQTT
    if (init_mqtt(MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT) != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read ADS1115 channels
        for (int i = 0; i < NUM_READINGS; i++) {
            int16_t reading = gpioRead(ADS1115_CHANNEL);
            if (reading < 0) {
                fprintf(stderr, "Error reading ADS1115 channel %d\n", ADS1115_CHANNEL);
                running = 0; // Exit if there's an error
                break;
            }

            // Validate reading
            if (reading < 0 || reading > 32767) {
                fprintf(stderr, "Error: Invalid reading from channel %d: %d\n", ADS1115_CHANNEL, reading);
                running = 0; // Exit if there's an error
                break;
            }

            // Publish reading
            if (publish_reading(ADS1115_CHANNEL, reading) != 0) {
                fprintf(stderr, "Error publishing reading from channel %d\n", ADS1115_CHANNEL);
                running = 0; // Exit if there's an error
                break;
            }

            // Wait for a short period
            gpioDelay(100); // 100ms
        }

        // Sleep for a short period
        gpioDelay(1000); // 1 second
    }

    // Clean up
    mosquitto_loop_stop(mqtt_client->client);
    mosquitto_disconnect(mqtt_client->client);
    mosquitto_destroy(mqtt_client->client);
    mosquitto_lib_cleanup();
    gpioTerminate();

    return 0;
}

