#define GPIO_DEVICE_1 "/dev/gpiochip0"
#define GPIO_DEVICE_2 "/dev/gpiochip1"

// Global variable to track program state
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
