// Function to initialize GPIO
int initialize_gpio(int gpio_number) {
    int fd;
    char dev_path[64];

    // Check if the GPIO device exists
    fd = open(dev_path, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO device %s: %s\n", dev_path, strerror(errno));
        return -1;
    }

    // Check if the GPIO device is a GPIO chip
    char chip_type[10];
    if (read(fd, chip_type, sizeof(chip_type)) < 0) {
        fprintf(stderr, "Error reading chip type from GPIO device %s: %s\n", dev_path, strerror(errno));
        close(fd);
        return -1;
    }

    if (strncmp(chip_type, "gpiochip", 8) != 0) {
        fprintf(stderr, "GPIO device %s is not a GPIO chip\n", dev_path);
        close(fd);
        return -1;
    }

    // Open the GPIO device
    fd = gpiod_chip_open(chip_type);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", chip_type, strerror(errno));
        close(fd);
        return -1;
