int initialize_gpio(int gpio_pin, int direction) {
    int fd;
    char buffer[64];

    fd = gpiod_export(gpio_pin, 0); // Export GPIO pin
    if (fd < 0) {
        fprintf(stderr, "Error exporting GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }

    // Set GPIO direction
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/direction", gpio_pin);
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO %d direction file: %s\n", gpio_pin, strerror(errno));
        gpiod_unexport(fd);
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        fprintf(stderr, "Error writing to GPIO %d direction file: %s\n", gpio_pin, strerror(errno));
        close(fd);
        gpiod_unexport(fd);
        return -1;
    }
    close(fd);

    return 0;
}

// Function to set GPIO value
int set_gpio_value(int gpio_pin, int value) {
    int fd;
    char buffer[64];

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/value", gpio_pin);
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO %d value file: %s\n", gpio_pin, strerror(errno));
        return -1;
    }

    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d\n", value);
        close(fd);
        return -1;
    }

    if (write(fd, value, 1) < 0) {
        fprintf(stderr, "Error writing to GPIO %d value file: %s\n", gpio_pin, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to report GPIO state
void report_gpio_state(int gpio_pin) {
    int fd;
    char buffer[64];
    char value_str[3];

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/value", gpio_pin);
    fd = open(buffer, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO %d value file: %s\n", gpio_pin, strerror(errno));
        return;
    }

    if (read(fd, value_str, 3) < 0) {
        fprintf(stderr, "Error reading GPIO %d value file: %s\n", gpio_pin, strerror(errno));
        close(fd);
        return;
    }

    close(fd);
    printf("GPIO %d: %s\n", gpio_pin, value_str);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio(GPIO_17, 0) < 0) {
        fprintf(stderr, "Failed to initialize GPIO %d\n", GPIO_17);
        return 1;
    }
    if (initialize_gpio(GPIO_23, 0) < 0) {
        fprintf(stderr, "Failed to initialize GPIO %d\n", GPIO_23);
        gpiod_unexport(GPIO_17);
        return 1;
    }
    if (initialize_gpio(GPIO_24, 0) < 0) {
        fprintf(stderr, "Failed to initialize GPIO %d\n", GPIO_24);
        gpiod_unexport(GPIO_17);
        gpiod_unexport(GPIO_23);
        return 1;
    }
    if (initialize_gpio(GPIO_25, 0) < 0) {
        fprintf(stderr, "Failed to initialize GPIO %d\n", GPIO_25);
        gpiod_unexport(GPIO_17);
        gpiod_unexport(GPIO_23);
        gpiod_unexport(GPIO_24);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set GPIO values
        if (set_gpio_value(GPIO_17, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d value\n", GPIO_17);
        }
        if (set_gpio_value(GPIO_23, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d value\n", GPIO_23);
        }
        if (set_gpio_value(GPIO_24, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d value\n", GPIO_24);
        }
        if (set_gpio_value(GPIO_25, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d value\n", GPIO_25);
        }

        // Report GPIO state
        report_gpio_state(GPIO_17);
        report_gpio_state(GPIO_23);
        report_gpio_state(GPIO_24);
        report_gpio_state(GPIO_25);

        // Delay
        usleep(10000); // 10ms
    }

    // Cleanup GPIO pins
    gpiod_unexport(GPIO_17);
    gpiod_unexport(GPIO_23);
    gpiod_unexport(GPIO_24);
    gpiod_unexport(GPIO_25);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define MQTT_BROKER_ADDRESS "localhost" // Change to your broker address
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // Channel 0 of MCP3008
#define READ_INTERVAL_MS 1000 // Read interval in milliseconds

// Global variables
static volatile int running = 1;
static int spi_handle;
static struct mosquitto *mosq = NULL;

// Function prototypes
int read_mcp3008(int channel);
void publish_mqtt(int sensor_value);
void signal_handler(int signal);

// Function to read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    gpioWrite(SPI_CHANNEL, 0); // Select the channel
    spiXfer(spi_handle, spi_data, spi_data, 3);
    gpioWrite(SPI_CHANNEL, 1); // Deselect the channel

    int adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];
    return adc_value;
}

// Function to publish MQTT message
void publish_mqtt(int sensor_value) {
    char message[50];
    snprintf(message, sizeof(message), "{\"sensor_value\": %d}", sensor_value);

    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(message), message, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Failed to publish MQTT message: %s\n", mosquitto_strerror(rc));
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory\n");
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, NULL);

    mosquitto_loop_start(mosq);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int sensor_value = read_mcp3008(MCP3008_CHANNEL);
        if (sensor_value < 0) {
            fprintf(stderr, "Error: Failed to read sensor value\n");
            sleep(READ_INTERVAL_MS);
            continue;
        }

        publish_mqtt(sensor_value);
        sleep(READ_INTERVAL_MS);
    }

    // Cleanup
    mosquitto_loop_stop(mosq);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

