// Function to open the camera device
int open_camera(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening camera device");
        return -1;
    }

    // Set the device to non-blocking mode
    if (ioctl(fd, VIDIOC_S_FMT, &IMAGE_FORMAT) == -1) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    // Set the image width and height
    if (ioctl(fd, VIDIOC_G_FMT, &IMAGE_FORMAT) == -1) {
        perror("Error getting format");
        close(fd);
        return -1;
    }

    // Allocate memory for the image data
    ImageData *image = (ImageData *)malloc(sizeof(ImageData));
    if (image == NULL) {
        perror("Error allocating memory for image");
        close(fd);
        return -1;
    }

    // Set the image dimensions
    image->width = IMAGE_WIDTH;
    image->height = IMAGE_HEIGHT;

    // Allocate memory for the image data
    image->data = (unsigned char *)malloc(image->width * image->height * 3);
    if (image->data == NULL) {
        perror("Error allocating memory for image data");
        free(image);
        close(fd);
        return -1;
    }

    // Set the buffer size
    if (ioctl(fd, VIDIOC_G_FMT, &IMAGE_FORMAT) == -1) {
        perror("Error getting format");
        free(image);
        close(fd);
        return -1;
    }

    // Capture the image
    if (capture_image(fd, image) == -1) {
        free(image);
        close(fd);
        return -1;
    }

    return fd;
}

