    if (close(fd) == -1) {
        perror("Error closing camera device");
        return -1;
    }
    return 0;
}

// Function to capture an image from the camera
int capture_image(int fd, ImageData *image) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("Error querying buffer");
        return -1;
    }

    buf.index = 0;

    if (ioctl(fd, VIDIOC_STREAMON, &buf) == -1) {
        perror("Error starting stream");
        return -1;
    }

    // Allocate memory for the image data
    image->data = (unsigned char *)malloc(buf.length);
    if (image->data == NULL) {
        perror("Error allocating memory for image data");
        return -1;
    }

    // Read the image data
    if (ioctl(fd, VIDIOC_READBUF, &buf) == -1) {
        perror("Error reading buffer");
        free(image->data);
        return -1;
    }

    // Set the image dimensions
    image->width = buf.width;
    image->height = buf.height;

    // Free the buffer memory
    free(image->data);

