    // Allocate memory for the image data
    image->data = (unsigned char *)malloc(image->width * image->height * 3);
    if (image->data == NULL) {
        perror("Error allocating memory for image data");
        return -1;
    }

    // Capture the image
    if (capture_image_raw(fd, image) == -1) {
        free(image->data);
        return -1;
    }

    return 0;
}

// Function to save the captured image to a file
int save_image(const char *filename, const ImageData *image) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    // Write the image data to the file
    if (fwrite(image->data, 1, image->width * image->height * 3, fp) != image->width * image->height * 3) {
        perror("Error writing to file");
        fclose(fp);
        return -1;
    }

    // Close the file
    if (fclose(fp) == -1) {
        perror("Error closing file");
        return -1;
    }

    return 0;
}

