// Define GPIO pins
#define PWM_PIN_1 4
#define PWM_PIN_2 5
#define PWM_PIN_3 6
#define PWM_PIN_4 7
#define PWM_PIN_5 8
#define PWM_PIN_6 9

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Define PWM duty cycle (0-100)
#define PWM_DUTY_CYCLE 100

// Global variable to track program state
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Error: Duty cycle out of range (0-255)\n");
        return;
    }

    gpioPWM(gpio, duty_cycle);
}

// Function to set PWM frequency
void set_pwm_frequency(int gpio, int frequency) {
    gpioSetPWMfrequency(gpio, frequency);
}

// Function to set PWM range
void set_pwm_range(int gpio, int range) {
    gpioSetPWMrange(gpio, range);
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

