    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);
    gpioSetMode(PWM_PIN_5, PI_OUTPUT);
    gpioSetMode(PWM_PIN_6, PI_OUTPUT);

    // Set PWM frequency
    set_pwm_frequency(PWM_PIN_1, PWM_FREQUENCY);
    set_pwm_frequency(PWM_PIN_2, PWM_FREQUENCY);
    set_pwm_frequency(PWM_PIN_3, PWM_FREQUENCY);
    set_pwm_frequency(PWM_PIN_4, PWM_FREQUENCY);
    set_pwm_frequency(PWM_PIN_5, PWM_FREQUENCY);
    set_pwm_frequency(PWM_PIN_6, PWM_FREQUENCY);

    // Set PWM range
    set_pwm_range(PWM_PIN_1, PWM_RANGE);
    set_pwm_range(PWM_PIN_2, PWM_RANGE);
