        return -1;
    }

    ret = gpiod_line_request_add(line_request);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to add line request for GPIO %d\n", GPIO_PIN);
        gpiod_line_release(line);
        gpiod_line_request_release(line_request);
        return -1;
