// Function to cleanup GPIO
int cleanup_gpio() {
    struct gpiod_line_request *line_request;
    struct gpiod_line *line;
    int ret;

    // Release GPIO line
    line_request = gpiod_line_request_new(GPIO_DEVICE, GPIO_PIN, 0);
    if (!line_request) {
        fprintf(stderr, "Error: Failed to request GPIO %d\n", GPIO_PIN);
        return -1;
    }

    line = gpiod_line_request_get_line(line_request);
    if (!line) {
        fprintf(stderr, "Error: Failed to get line for GPIO %d\n", GPIO_PIN);
        gpiod_line_request_release(line_request);
        return -1;
    }

    ret = gpiod_line_request_add(line_request);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to add line request for GPIO %d\n", GPIO_PIN);
        gpiod_line_release(line);
        gpiod_line_request_release(line_request);
        return -1;
    }

    ret = gpiod_line_request_release(line_request);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to release line request for GPIO %d\n", GPIO_PIN);
        gpiod_line_release(line);
        gpiod_line_request_release(line_request);
        return -1;
    }

