int gpio_write(int pin, int value) {
    struct gpiod_line_request *request = malloc(sizeof(struct gpiod_line_request));
    if (!request) {
        perror("Failed to allocate memory for gpio_write_request");
        return -1;
    }

    request->type = GPID_LINE;
    request->line = pin;
    request->value = value;

    int ret = gpiod_set_value(request);
    free(request->value);
    free(request);
    return ret;
}

