int gpio_read(int pin) {
    struct gpiod_line_request *request = malloc(sizeof(struct gpiod_line_request));
    if (!request) {
        perror("Failed to allocate memory for gpio_read_request");
        return -1;
    }

    request->type = GPID_LINE;
    request->line = pin;

    int ret = gpiod_get_value(request);
    free(request->value);
    return ret;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Export GPIO pins
    if (gpio_export(GPIO_PIN_1) < 0 || gpio_export(GPIO_PIN_2) < 0) {
        fprintf(stderr, "Failed to export GPIO pins. Exiting.\n");
        return 1;
    }

    // Set GPIO directions
    if (gpio_set_direction(GPIO_PIN_1, "in") < 0 || gpio_set_direction(GPIO_PIN_2, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO directions. Exiting.\n");
        gpio_unexport(GPIO_PIN_1);
        gpio_unexport(GPIO_PIN_2);
        return 1;
    }

    // Main loop
    while (1) {
        // Read GPIO values
        int value_1 = gpio_read(GPIO_PIN_1);
        int value_2 = gpio_read(GPIO_PIN_2);

        // Check for errors
        if (value_1 < 0 || value_2 < 0) {
            fprintf(stderr, "Error reading GPIO values. Continuing.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Check if GPIO pins are set to the correct values
        if (value_1 != gpio_state_1 || value_2 != gpio_state_2) {
            fprintf(stderr, "GPIO pins are not set to the correct values. Exiting.\n");
            gpio_unexport(GPIO_PIN_1);
            gpio_unexport(GPIO_PIN_2);
            return 1;
        }

        // Print the current state
        printf("GPIO Pin 1: %d, GPIO Pin 2: %d\n", value_1, value_2);

        // Delay for 1 second
        sleep(1);
    }

    // Unexport GPIO pins before exiting (this will not be reached in the infinite loop)
    gpio_unexport(GPIO_PIN_1);
    gpio_unexport(GPIO_PIN_2);

    return 0;
}

