// Function to initialize GPIO pins
int initialize_gpio(int trigger_pin, int echo_pin) {
    int ret = gpiod_line_request(trigger_pin, "trigger", GPIOD_LINE_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error requesting trigger line: %d\n", ret);
        return -1;
    }

    ret = gpiod_line_request(echo_pin, "echo", GPIOD_LINE_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Error requesting echo line: %d\n", ret);
        return -1;
    }

    return 0;
