// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpio_set_direction(TRIGGER_PIN, GPIOD_DIR_OUTPUT);
    gpio_set_value(TRIGGER_PIN, 1);
    usleep(10); // 10us trigger pulse
    gpio_set_value(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration
long measure_echo_duration() {
    long start_time = 0;
    long end_time = 0;

    // Wait for the echo pin to go high
    while (gpio_get_level(ECHO_PIN) == 0) {
        usleep(1); // Wait 1 us
    }

    start_time = gpio_get_time();

    // Wait for the echo pin to go low
    while (gpio_get_level(ECHO_PIN) == 1) {
        usleep(1); // Wait 1 us
    }

    end_time = gpio_get_time();

    return end_time - start_time;
}

// Function to calculate the distance in centimeters
float calculate_distance(long duration) {
    return (float)duration / 58; // Speed of sound in cm/us
}

// Function to report the distance
void report_distance(float distance) {
    printf("Distance: %.2f cm\n", distance);
