// Define the I2C address of the PCF8574
#define PCF8574_ADDR 0x70

// Define the register addresses for the PCF8574
#define PCF8574_REG_CONFIG 0x00
#define PCF8574_REG_DATA 0x01

// Define the number of registers to read
#define NUM_REGISTERS 4

// Define the I2C bus number
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pcf8574();
int read_data(int reg_addr, int *data);
void display_data(int data[], int num_registers);
void cleanup();
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int num_leds;
    int num_digits;
    int num_columns;
} pcf8574_config_t;

pcf8574_config_t config = {
    .num_leds = 8,
    .num_digits = 4,
    .num_columns = 8
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, PCF8574_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the PCF8574
    if (init_pcf8574() != 0) {
        fprintf(stderr, "PCF8574 initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int data[NUM_REGISTERS];
        int num_read = read_data(PCF8574_REG_CONFIG, data);
        if (num_read == 0) {
            fprintf(stderr, "Failed to read configuration data\n");
            continue; // Continue to the next iteration
        }

        display_data(data, config.num_digits);
        gpioDelay(1000); // Display every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize the PCF8574
int init_pcf8574() {
    // Configure the PCF8574 for 8-bit data, 8-bit address, and 8-bit clock
    if (i2cWriteByteData(i2c_handle, PCF8574_REG_CONFIG, 0x07) < 0) {
        fprintf(stderr, "Failed to write to config register\n");
        return -1;
    }
    return 0;
}

// Read data from the PCF8574
int read_data(int reg_addr, int *data) {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, reg_addr, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read data from register 0x%02X: %d\n", reg_addr, bytes_read);
        return -1;
    }

    *data = (buf[0] << 8) | buf[1];
    return 0;
}

// Display the data on the PCF8574
void display_data(int data[], int num_registers) {
    for (int i = 0; i < num_registers; i++) {
        if (i < num_digits) {
            for (int j = 0; j < config.num_columns; j++) {
                if (data[i] & (1 << j)) {
                    i2cWriteByteData(i2c_handle, PCF8574_REG_DATA, 1); // 1 for on, 0 for off
                } else {
                    i2cWriteByteData(i2c_handle, PCF8574_REG_DATA, 0); // 0 for off
                }
            }
        } else {
            for (int j = 0; j < config.num_columns; j++) {
                i2cWriteByteData(i2c_handle, PCF8574_REG_DATA, 0); // 0 for off
            }
        }
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

