// Structure to hold GPIO information
typedef struct {
    int gpio;
    char *direction;
} gpio_t;

// Function to export a GPIO pin
int gpio_export(int gpio) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", gpio);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error writing to /sys/class/gpio/export: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int gpio) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", gpio);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error writing to /sys/class/gpio/unexport: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the direction of a GPIO pin
int gpio_set_direction(int gpio, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", gpio);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to write a value to a GPIO pin
int gpio_write(int gpio, int value) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    snprintf(value_str, sizeof(value_str), "%d", value);
    if (write(fd, value_str, strlen(value_str)) != strlen(value_str)) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read a value from a GPIO pin
int gpio_read(int gpio) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (read(fd, value_str, strlen(value_str)) < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

// Function to check if a device is present
int check_device_absence(int gpio) {
    FILE *fp;
    char buffer[64];
    int fd;

    fp = fopen("/sys/class/gpio/gpio%d/export", O_WRONLY);
    if (fp == NULL) {
        fprintf(stderr, "Error opening /sys/class/gpio/gpio%d/export: %s\n", gpio, strerror(errno));
        return -1;
    }

    if (fwrite("0", 1, 1, fp) != 1) {
        fprintf(stderr, "Error writing to /sys/class/gpio/gpio%d/export: %s\n", gpio, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    fp = fopen("/sys/class/gpio/gpio%d/direction", O_WRONLY);
    if (fp == NULL) {
        fprintf(stderr, "Error opening /sys/class/gpio/gpio%d/direction: %s\n", gpio, strerror(errno));
        return -1;
    }

    if (fwrite("in", 1, 1, fp) != 1) {
        fprintf(stderr, "Error writing to /sys/class/gpio/gpio%d/direction: %s\n", gpio, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    fp = fopen("/sys/class/gpio/gpio%d/value", O_RDONLY);
    if (fp == NULL) {
        fprintf(stderr, "Error opening /sys/class/gpio/gpio%d/value: %s\n", gpio, strerror(errno));
        return -1;
    }

    if (fread(&buffer, 1, 1, fp) != 1) {
        fprintf(stderr, "Error reading from /sys/class/gpio/gpio%d/value: %s\n", gpio, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    return (buffer == "1") ? 0 : 1;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

