#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>
#include <string.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

// Define GPIO device names
#define GPIO_DEVICE_1 "/dev/gpiochip0"
#define GPIO_DEVICE_2 "/dev/gpiochip1"

// Global variable to track program state
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize a GPIO pin
int initialize_gpio(int gpio_pin) {
    int fd;
    char buf[64];

    fd = gpiod_export(gpio_pin, 0); // Export GPIO pin
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to export GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }

    snprintf(buf, sizeof(buf), "/sys/class/gpio/gpio%d/direction", gpio_pin);
    fd = open(buf, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO %d direction file: %s\n", gpio_pin, strerror(errno));
        gpiod_unexport(fd);
        return -1;
    }

    if (write(fd, "out", 3) < 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d direction file: %s\n", gpio_pin, strerror(errno));
        close(fd);
        gpiod_unexport(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to uninitialize a GPIO pin
int uninitialize_gpio(int gpio_pin) {
    int fd;
    char buf[64];

    fd = gpiod_export(gpio_pin, 0); // Export GPIO pin
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to export GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }

    snprintf(buf, sizeof(buf), "/sys/class/gpio/gpio%d/direction", gpio_pin);
    fd = open(buf, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO %d direction file: %s\n", gpio_pin, strerror(errno));
        close(fd);
        gpiod_unexport(fd);
        return -1;
    }

    if (write(fd, "in", 2) < 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d direction file: %s\n", gpio_pin, strerror(errno));
        close(fd);
        gpiod_unexport(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the state of a GPIO pin
int set_gpio_state(int gpio_pin, int state) {
    int fd;
    char buf[64];

    snprintf(buf, sizeof(buf), "/sys/class/gpio/gpio%d/value", gpio_pin);
    fd = open(buf, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO %d value file: %s\n", gpio_pin, strerror(errno));
        return -1;
    }

    if (state == 1) {
        if (write(fd, "1", 1) < 0) {
            fprintf(stderr, "Error: Failed to write to GPIO %d value file: %s\n", gpio_pin, strerror(errno));
            close(fd);
            return -1;
        }
    } else {
        if (write(fd, "0", 1) < 0) {
            fprintf(stderr, "Error: Failed to write to GPIO %d value file: %s\n", gpio_pin, strerror(errno));
            close(fd);
            return -1;
        }
    }

    close(fd);
    return 0;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio(GPIO_17) < 0 || initialize_gpio(GPIO_22) < 0 || initialize_gpio(GPIO_27) < 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO pins. Exiting.\n");
        return 1;
    }

    printf("GPIO pins initialized successfully.\n");

    // Main loop
    while (program_running) {
        // Set GPIO 17 HIGH
        if (set_gpio_state(GPIO_17, 1) < 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d HIGH\n", GPIO_17);
        }

        // Set GPIO 22 LOW
        if (set_gpio_state(GPIO_22, 0) < 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d LOW\n", GPIO_22);
        }

        // Set GPIO 27 HIGH
        if (set_gpio_state(GPIO_27, 1) < 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d HIGH\n", GPIO_27);
        }

        // Delay for 1 second
        sleep(1);
    }

    // Cleanup GPIO pins before exiting
    uninitialize_gpio(GPIO_17);
    uninitialize_gpio(GPIO_22);
    uninitialize_gpio(GPIO_27);

    printf("GPIO pins uninitialized successfully.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define PWM_PIN1 17
#define PWM_PIN2 18
#define PWM_PIN3 22
#define PWM_PIN4 27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM range
#define PWM_RANGE 1000

// Define PWM duty cycle range
#define PWM_DUTY_CYCLE_MIN 0
#define PWM_DUTY_CYCLE_MAX PWM_RANGE

// Global variable for PWM control
int pwm_handle1 = -1;
int pwm_handle2 = -1;
int pwm_handle3 = -1;
int pwm_handle4 = -1;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
void set_pwm_frequency(int pin, int frequency);
void set_pwm_range(int pin, int range);
void set_pwm_duty_cycle(int pin, int duty_cycle);
void cleanup_gpio_interrupt();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM pins as output
    gpioSetMode(PWM_PIN1, PI_OUTPUT);
    gpioSetMode(PWM_PIN2, PI_OUTPUT);
    gpioSetMode(PWM_PIN3, PI_OUTPUT);
    gpioSetMode(PWM_PIN4, PI_OUTPUT);

    // Set PWM frequency
    set_pwm_frequency(PWM_PIN1, PWM_FREQUENCY);
    set_pwm_frequency(PWM_PIN2, PWM_FREQUENCY);
    set_pwm_frequency(PWM_PIN3, PWM_FREQUENCY);
    set_pwm_frequency(PWM_PIN4, PWM_FREQUENCY);

    // Set PWM range
    set_pwm_range(PWM_PIN1, PWM_RANGE);
    set_pwm_range(PWM_PIN2, PWM_RANGE);
    set_pwm_range(PWM_PIN3, PWM_RANGE);
    set_pwm_range(PWM_PIN4, PWM_RANGE);

    // Set PWM duty cycle
    set_pwm_duty_cycle(PWM_PIN1, PWM_DUTY_CYCLE_MIN);
    set_pwm_duty_cycle(PWM_PIN2, PWM_DUTY_CYCLE_MIN);
    set_pwm_duty_cycle(PWM_PIN3, PWM_DUTY_CYCLE_MIN);
    set_pwm_duty_cycle(PWM_PIN4, PWM_DUTY_CYCLE_MIN);

    // Set PWM interrupt on rising edge
    gpioSetISRFuncEx(PWM_PIN1, RISING_EDGE, 0, cleanup_gpio_interrupt, NULL);
    gpioSetISRFuncEx(PWM_PIN2, RISING_EDGE, 0, cleanup_gpio_interrupt, NULL);
    gpioSetISRFuncEx(PWM_PIN3, RISING_EDGE, 0, cleanup_gpio_interrupt, NULL);
    gpioSetISRFuncEx(PWM_PIN4, RISING_EDGE, 0, cleanup_gpio_interrupt, NULL);

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio() {
    if (pwm_handle1 >= 0) {
        gpioPWM(PWM_PIN1, 0); // Stop PWM
        pwm_handle1 = -1;
    }
    if (pwm_handle2 >= 0) {
        gpioPWM(PWM_PIN2, 0); // Stop PWM
        pwm_handle2 = -1;
    }
    if (pwm_handle3 >= 0) {
        gpioPWM(PWM_PIN3, 0); // Stop PWM
        pwm_handle3 = -1;
    }
    if (pwm_handle4 >= 0) {
        gpioPWM(PWM_PIN4, 0); // Stop PWM
        pwm_handle4 = -1;
    }
}

// Set PWM frequency
void set_pwm_frequency(int pin, int frequency) {
    gpioSetPWMfrequency(pin, frequency);
}

// Set PWM range
void set_pwm_range(int pin, int range) {
    gpioSetPWMrange(pin, range);
}

// Set PWM duty cycle
void set_pwm_duty_cycle(int pin, int duty_cycle) {
    gpioPWM(pin, duty_cycle);
}

// Interrupt handler for PWM interrupt
void cleanup_gpio_interrupt() {
    gpioPWM(PWM_PIN1, 0); // Stop PWM
    gpioPWM(PWM_PIN2, 0); // Stop PWM
    gpioPWM(PWM_PIN3, 0); // Stop PWM
    gpioPWM(PWM_PIN4, 0); // Stop PWM
    pwm_handle1 = -1;
    pwm_handle2 = -1;
    pwm_handle3 = -1;
    pwm_handle4 = -1;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set PWM frequency for all PWM pins
    set_pwm_frequency(PWM_PIN1, PWM_FREQUENCY);
    set_pwm_frequency(PWM_PIN2, PWM_FREQUENCY);
    set_pwm_frequency(PWM_PIN3, PWM_FREQUENCY);
    set_pwm_frequency(PWM_PIN4, PWM_FREQUENCY);

    // Set PWM range for all PWM pins
    set_pwm_range(PWM_PIN1, PWM_RANGE);
    set_pwm_range(PWM_PIN2, PWM_RANGE);
    set_pwm_range(PWM_PIN3, PWM_RANGE);
    set_pwm_range(PWM_PIN4, PWM_RANGE);

