// Define GPIO pin and GPIO device
#define GPIO_PIN 17
#define GPIO_DEVICE "gpiochip0"

// Global variable to track program state
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize GPIO
int initialize_gpio() {
    struct gpiod_line_request *request;
    struct gpiod_line *line;
    int ret;

    // Request GPIO 17 as output
    request = gpiod_line_request_request_gpio(GPIO_DEVICE, GPIO_PIN, 0);
    if (!request) {
        fprintf(stderr, "Error: Could not request GPIO %d\n", GPIO_PIN);
        return -1;
    }

    // Request GPIO 17 as direction output
    line = gpiod_line_request_request_direction(GPIO_DEVICE, GPIO_PIN, 0);
    if (!line) {
        fprintf(stderr, "Error: Could not request GPIO %d direction\n", GPIO_PIN);
        gpiod_line_release(line);
        return -1;
    }

    // Attach the line to the GPIO
    ret = gpiod_line_add(line);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not add GPIO %d line\n", GPIO_PIN);
        gpiod_line_release(line);
        gpiod_line_release(request);
        return -1;
    }

    // Set the GPIO direction to output
    ret = gpiod_line_set_direction(GPIO_DEVICE, GPIO_PIN, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO %d direction\n", GPIO_PIN);
        gpiod_line_release(line);
        gpiod_line_release(request);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio() {
    struct gpiod_line_request *request;
    struct gpiod_line *line;
    int ret;

    // Release the GPIO line
    request = gpiod_line_request_get(GPIO_DEVICE, GPIO_PIN);
    if (request) {
        line = gpiod_line_request_get(GPIO_DEVICE, GPIO_PIN);
        if (line) {
            ret = gpiod_line_release(line);
            if (ret < 0) {
                fprintf(stderr, "Error: Could not release GPIO %d line\n", GPIO_PIN);
            }
        }
        gpiod_line_release(request);
    }
}

// Function to report the GPIO state
void report_gpio_state() {
    printf("GPIO %d: %s\n", GPIO_PIN, gpiod_line_get_value(GPIO_DEVICE, GPIO_PIN) ? "HIGH" : "LOW");
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error: GPIO initialization failed\n");
        return 1;
    }

    printf("GPIO %d initialized successfully.\n", GPIO_PIN);

    // Main loop
    while (program_running) {
        report_gpio_state();
        sleep(0.05);
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

