float calculate_distance(int pulse_width) {
    if (pulse_width < PULSE_WIDTH_MIN || pulse_width > PULSE_WIDTH_MAX) {
        fprintf(stderr, "Error: Invalid pulse width: %d\n", pulse_width);
        return -1.0; // Indicate error
    }

    float distance = (float)pulse_width * 0.0343 / 2.0; // Speed of sound in cm/us * 0.0343 us/cm / 2
    return distance;
}

