        gpio_set_value(pin, 1);
        usleep(1);
        gpio_set_value(pin, 0);
        usleep(1);

        if (gpio_get_value(pin)) {
            data[j / 8] |= (1 << (7 - (j % 8)));
        }
        j++;
    }

    // Check checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "Error: Checksum failed\n");
        return -1;
    }

