int read_dht22(int pin, float *temperature, float *humidity) {
    unsigned char data[5];
    int result;
    int i;

    // Set pin to input mode
    gpio_t gpio = {pin, GPIOD_IN};
    if (gpiod_pin_request_mode(gpio.pin, GPIOD_MODE_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO %d as input\n", gpio.pin);
        return -1;
    }

    // Wait for DHT22 to be ready (at least 1ms)
    usleep(1000); // 1ms

    // Read 5 bytes of data
    for (i = 0; i < 5; i++) {
        gpio_t gpio = {pin, GPIOD_IN};
        if (gpiod_pin_request_mode(gpio.pin, GPIOD_MODE_INPUT) < 0) {
            fprintf(stderr, "Error: Failed to request GPIO %d as input\n", gpio.pin);
            return -1;
        }
        usleep(1); // Small delay to avoid busy-waiting

        if (gpio_pin_get_value(gpio.pin) == 0) {
            // DHT22 is low
            data[i] = 0;
        } else {
            // DHT22 is high
            data[i] = 1;
        }
    }

    // Verify checksum
    if (data[4] != (data[0] + data[1] + data[2] + data[3]) & 0xFF) {
        fprintf(stderr, "Error: DHT22 checksum failed\n");
        return -1;
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) | data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    return 0;
}

