#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define MAX31855 register addresses
#define MAX31855_REG_ID 0x00
#define MAX31855_REG_TEMP_MSB 0x01
#define MAX31855_REG_TEMP_LSB 0x02
#define MAX31855_REG_PRESENT 0x03
#define MAX31855_REG_CONFIG 0x04

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_register(int handle, uint8_t reg_addr);
int spi_write_register(int handle, uint8_t reg_addr, uint8_t value);
int read_max31855(int handle, float *temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read a register from the MAX31855
int spi_read_register(int handle, uint8_t reg_addr) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg_addr, strerror(errno));
        return -1;
    }

    return rx_buf[1];
}

// Function to write a register to the MAX31855
int spi_write_register(int handle, uint8_t reg_addr, uint8_t value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write operation
    tx_buf[1] = value;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg_addr, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read temperature from the MAX31855
int read_max31855(int handle, float *temperature) {
    uint8_t temp_msb, temp_lsb;
    int result;

    // Read temperature MSB
    result = spi_read_register(handle, MAX31855_REG_TEMP_MSB);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature MSB: %s\n", strerror(errno));
        return -1;
    }
    temp_msb = (result >> 4) & 0x0F; // Extract MSB

    // Read temperature LSB
    result = spi_read_register(handle, MAX31855_REG_TEMP_LSB);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature LSB: %s\n", strerror(errno));
        return -1;
    }
    temp_lsb = (result >> 4) & 0x0F; // Extract LSB

    // Check for presence of the MAX31855
    if (temp_msb == 0x00 || temp_msb == 0x01) {
        fprintf(stderr, "Error: MAX31855 not detected. Check wiring.\n");
        return -1;
    }

    // Read PRESENT register
    result = spi_read_register(handle, MAX31855_REG_PRESENT);
    if (result < 0) {
        fprintf(stderr, "Error reading PRESENT register: %s\n", strerror(errno));
        return -1;
    }

    // Check PRESENT bit
    if (result & 0x01) {
        fprintf(stderr, "Error: MAX31855 not present.\n");
        return -1;
    }

    // Read CONFIG register
    result = spi_read_register(handle, MAX31855_REG_CONFIG);
    if (result < 0) {
        fprintf(stderr, "Error reading CONFIG register: %s\n", strerror(errno));
        return -1;
    }

    // Extract temperature from the MSB
    *temperature = (float)((temp_msb << 8) | temp_lsb) / 10.0;

    return 0;
}

int main() {
    float temperature;
    int spi_handle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Configure MAX31855 (example configuration)
    spi_write_register(spi_handle, 0x01, 0x00); // Reset
    spi_write_register(spi_handle, 0x02, 0x00); // Enable
    spi_write_register(spi_handle, 0x03, 0x00); // Configuration register
    spi_write_register(spi_handle, 0x04, 0x00); // Prescaler
    spi_write_register(spi_handle, 0x05, 0x00); // Temperature conversion register

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_max31855(spi_handle, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

