    // Wait for the trigger pin to go low
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(trigger_line) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) == 0) {
