int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Error: Duty cycle must be between 0 and %d\n", PWM_RANGE);
        return -1;
    }

    int result = gpioPWM(gpio, duty_cycle);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle on GPIO %d: %d\n", gpio, result);
        return -1;
    }
    return 0;
}

