    // Set PWM range
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(PWM_PIN, 1000); // 1 kHz

    // Set up interrupt handler for PWM overflow
    gpioSetISRFuncEx(PWM_PIN, RISING_EDGE, 0, pwm_isr, NULL);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("PWM control program started. Press Ctrl+C to exit.\n");

    // Keep the program running until a signal is received
    while (!terminate) {
        sleep(1);
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    printf("PWM control program terminated.\n");

    return 0;
}

// ISR function for PWM overflow
void pwm_isr(int gpio, int level, uint32_t tick, void *user) {
    // This function is called when the PWM overflow interrupt is triggered
    // It increments a counter, which can be used to control the PWM duty cycle
    // in a separate thread.
    // In this example, we simply increment a global variable.
    static int counter = 0;
    counter++;
}

