#define TCS34725_REG_CONTROL 0x0F
#define TCS34725_REG_DATA_RATE 0x0E
#define TCS34725_REG_RESULT_RATE 0x0F
#define TCS34725_REG_MEASUREMENT_CONFIG 0x10
#define TCS34725_REG_MEASUREMENT_MODE 0x11
#define TCS34725_REG_ID 0x12

