void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the TCS34725
int tcs34725_init(int i2c_handle) {
    // Check device ID
    int id = i2cReadByteData(i2c_handle, TCS34725_REG_ID);
    if (id != 0xAE) {
        fprintf(stderr, "Error: TCS34725 not found (ID: 0x%x)\n", id);
        return -1;
    }

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, TCS34725_REG_CONTROL, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write to control register (0x01)\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, TCS34725_REG_DATA_RATE, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to write to data rate register (0x03)\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, TCS34725_REG_MEASUREMENT_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write to measurement config register (0x00)\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, TCS34725_REG_MEASUREMENT_MODE, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write to measurement mode register (0x01)\n");
        return -1;
    }

    return 0;
}

// Function to read a single register from the TCS34725
int tcs34725_read_register(int i2c_handle, uint8_t reg) {
    int value = i2cReadByteData(i2c_handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read register 0x%02x (errno: %d)\n", reg, errno);
        return -1;
    }
    return value;
}

// Function to read a single measurement from the TCS34725
int tcs34725_read_measurement(int i2c_handle) {
    int data_rate = i2cReadByteData(i2c_handle, TCS34725_REG_DATA_RATE);
    if (data_rate < 0) {
        fprintf(stderr, "Error: Failed to read data rate register (errno: %d)\n", errno);
        return -1;
    }

    int result_rate = i2cReadByteData(i2c_handle, TCS34725_REG_RESULT_RATE);
    if (result_rate < 0) {
        fprintf(stderr, "Error: Failed to read result rate register (errno: %d)\n", errno);
        return -1;
    }

    int id = i2cReadByteData(i2c_handle, TCS34725_REG_ID);
    if (id < 0) {
        fprintf(stderr, "Error: Failed to read ID register (errno: %d)\n", errno);
        return -1;
    }

    // Read the measurement data
    uint8_t data[6];
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_REG_DATA_RATE, (char *)data, 6) < 0) {
        fprintf(stderr, "Error: Failed to read measurement data (errno: %d)\n", errno);
        return -1;
    }

    // Combine the two bytes for each register
    int16_t raw_value = (data[0] << 8) | data[1];
    int16_t raw_value_msb = (data[2] << 8) | data[3];
    int16_t raw_value_lsb = (data[4] << 8) | data[5];

    // Convert to physical units (example conversion, adjust as needed)
    int16_t raw_value_physical = (raw_value_msb << 8) | raw_value_lsb;

    return raw_value_physical;
}

