        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, TCS34725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (errno: %d)\n", errno);
        gpioTerminate();
        return 1;
    }

    // Initialize the TCS34725 sensor
