        gpiod_line_close(fd);
        return -1;
    }

    // Export GPIO line
    if (gpiod_line_export(fd, "out") < 0) {
        fprintf(stderr, "Error exporting GPIO line %d\n", gpio_number);
        gpiod_line_close(fd);
        gpiod_line_unexport(fd);
        return -1;
    }

    // Set GPIO direction to output
    char direction_path[50];
    snprintf(direction_path, sizeof(direction_path), "/sys/class/gpio/gpio%d/direction", gpio_number);
