#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>
#include <string.h>

// Define GPIO pin and GPIO device
#define GPIO_PIN 18
#define GPIO_DEVICE "gpiochip0"

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pin
int initialize_gpio(int pin) {
    struct gpiod_line *line;
    int ret;

    // Open the GPIO line
    line = gpiod_line_open(GPIO_DEVICE, pin);
    if (!line) {
        fprintf(stderr, "Error opening GPIO line %d: %s\n", pin, gpiod_error_to_str(gpiod_error_from_errno(errno)));
        return -1;
    }

    // Set the GPIO direction to output
    ret = gpiod_line_set_direction(line, GPIOD_DIRECTION_OUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO direction for pin %d: %s\n", pin, gpiod_error_to_str(gpiod_error_from_errno(errno)));
        gpiod_line_close(line);
        return -1;
    }

    // Export the GPIO pin
    ret = gpiod_export(GPIO_DEVICE, GPIO_PIN, 0);
    if (ret < 0) {
        fprintf(stderr, "Error exporting GPIO pin %d: %s\n", GPIO_PIN, gpiod_error_to_str(gpiod_error_from_errno(errno)));
        gpiod_line_close(line);
        return -1;
    }

    return 0;
}

// Function to set the GPIO pin value
int set_gpio_value(int pin, int value) {
    struct gpiod_line *line;
    int ret;

    // Open the GPIO line
    line = gpiod_line_open(GPIO_DEVICE, pin);
    if (!line) {
        fprintf(stderr, "Error opening GPIO line %d: %s\n", pin, gpiod_error_to_str(gpiod_error_from_errno(errno)));
        return -1;
    }

    // Set the GPIO value
    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value for pin %d: %s\n", pin, gpiod_error_to_str(gpiod_error_from_errno(errno)));
        gpiod_line_close(line);
        return -1;
    }

    // Close the GPIO line
    gpiod_line_close(line);
    return 0;
}

// Function to read the GPIO pin value
int read_gpio_value(int pin) {
    struct gpiod_line *line;
    int ret;
    int value;

    // Open the GPIO line
    line = gpiod_line_open(GPIO_DEVICE, pin);
    if (!line) {
        fprintf(stderr, "Error opening GPIO line %d: %s\n", pin, gpiod_error_to_str(gpiod_error_from_errno(errno)));
        return -1;
    }

    // Read the GPIO value
    ret = gpiod_line_get_value(line, &value);
    if (ret < 0) {
        fprintf(stderr, "Error reading GPIO value for pin %d: %s\n", pin, gpiod_error_to_str(gpiod_error_from_errno(errno)));
        gpiod_line_close(line);
        return -1;
    }

    // Close the GPIO line
    gpiod_line_close(line);
    return value;
}

// Function to cleanup GPIO resources
void cleanup_gpio(int pin) {
    struct gpiod_line *line;
    int ret;

    // Close the GPIO line
    line = gpiod_line_open(GPIO_DEVICE, pin);
    if (line) {
        gpiod_line_close(line);
    }
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("GPIO initialized successfully.\n");

    // Main loop
    while (program_running) {
        int value = read_gpio_value(GPIO_PIN);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO value. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        printf("GPIO value: %d\n", value);

        // Set the GPIO value
        if (set_gpio_value(GPIO_PIN, value) < 0) {
            fprintf(stderr, "Failed to set GPIO value. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Delay to avoid overwhelming the system
        usleep(100000); // 100ms
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio(GPIO_PIN);

    printf("GPIO cleanup complete.\n");

    return 0;
}

