#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to read a 16-bit value from the MPU6050
int16_t read_register(int handle, uint8_t reg) {
    int16_t value = i2cReadWordData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to write a 16-bit value to the MPU6050
int write_register(int handle, uint8_t reg, int16_t value) {
    int result = i2cWriteWordData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1; // Indicate error
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU6050 (set PWR_MGMT_1 to 0)
    if (write_register(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error waking up MPU6050\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read accelerometer data
        int16_t accel_x = read_register(i2c_handle, ACCEL_XOUT_H);
        int16_t accel_y = read_register(i2c_handle, ACCEL_YOUT_H);
        int16_t accel_z = read_register(i2c_handle, ACCEL_ZOUT_H);

        // Read gyroscope data
        int16_t gyro_x = read_register(i2c_handle, GYRO_XOUT_H);
        int16_t gyro_y = read_register(i2c_handle, GYRO_YOUT_H);
        int16_t gyro_z = read_register(i2c_handle, GYRO_ZOUT_H);

        // Print the readings
        printf("Accel: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);
        printf("Gyro: X=%d, Y=%d, Z=%d\n", gyro_x, gyro_y, gyro_z);

        // Delay for 1 second
        gpioDelay(1000);
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pin and GPIO mode
#define GPIO_PIN 17
#define GPIO_MODE GPIOD_OUTPUT

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the GPIO pin output state
int set_gpio_output(int pin, int value) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_line_get(pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", pin);
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO %d value to %d\n", pin, value);
        gpiod_line_release(line);
        return -1;
    }

    printf("GPIO %d set to %d\n", pin, value);
    return 0;
}

int main() {
    int ret;
    int current_state;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize libgpiod
    if (gpiod_line_request_output(GPIO_PIN, GPIO_MODE, 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d output\n", GPIO_PIN);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read the current GPIO state
        current_state = gpiod_line_get_value(GPIO_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error: Could not get GPIO %d value\n", GPIO_PIN);
            break; // Exit loop on error
        }

        // Set the GPIO pin output state
        ret = set_gpio_output(GPIO_PIN, current_state);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d to %d\n", GPIO_PIN, current_state);
            break; // Exit loop on error
        }

        // Wait for 0.6 seconds
        sleep(0.6);
    }

    // Release the GPIO line on exit
    gpiod_line_release(GPIO_PIN);

    return 0;
}

